// The work item — the queue's one durable object (tasks-dispatch DESIGN §3, §4).
// An issue titled `[claudinite-work] <pack>/<task> [qualifier]`, whose labels are
// its state, whose body's first line is the task path, and whose two optional body
// fields (`Not-before`, `Blocked-by`) are the only scheduling facts it carries.
//
// PURE, and deliberately the whole schema: everything else — anchors, guards,
// yields, leashes, verdicts — is computed fresh at every tick and pick from the
// engine and the declarations at HEAD (DESIGN §14). The label-and-field vocabulary
// here is therefore the compatibility surface across engine versions, which is why
// additive change is the strongly preferred shape and a rename needs a migration.
//
// Parse/serialize of the two fields lives here and nowhere else (DESIGN §9).
//
// The one import, and a frozen constant at that: the pack-rename map, which this
// module needs to keep reading titles written before a rename (see parseWorkItemTitle).
import { canonicalPackId } from '../../pack_loader/renamed-packs.mjs';

// The title prefix. Disjoint from the slot mechanism's `[claudinite-task]` on
// purpose: the two mechanisms coexist per-repo behind `taskScheduler.dispatch`,
// and neither may read the other's issues (DESIGN §14, S29).
export const WORK_PREFIX = '[claudinite-work]';

export const BLOCKED = 'task:blocked';
export const READY = 'task:ready';
export const URGENT = 'task:urgent';
export const EXECUTING = 'task:executing';
export const AGENT = 'task:agent';
export const ORIGIN_SCHEDULE = 'origin:schedule';
export const NEEDS_HUMAN = 'needs-human';

// The TRIAGE SUB-LABELS. `needs-human` says an item is parked; these say what the
// human parked with it is expected to DO, which is the whole difference between a
// queue a person can skim and one they have to read. Every park wears BOTH:
// `needs-human` stays the single state the machine reads (every guard, sweep and
// dashboard already turns on it), and the sub-label is the human's routing.
//
// The four are disjoint by REMEDY, not by cause:
//   action   — something outside the code must change: a secret set, a scope
//              granted, a routine's prompt or endpoint fixed, an item re-created
//              with the parameter it was missing. Mechanical; no judgement.
//   decision — the run stopped mid-flight and what happens next is a choice:
//              re-queue or abandon, does the half-done work stand, was the
//              ceiling violation acceptable.
//   approval — the run SUCCEEDED and deliberately left an unmerged PR. The only
//              park that is not a fault; the human merges it or closes it.
//   failure  — the run broke: a bug, a contract-forbidden shape, a malformed or
//              forged item. Someone diagnoses and fixes code.
// `failure` is the default a park falls back to, so an unclassified park reads as
// "diagnose me" rather than quietly joining the mechanical lane.
const triage = (kind) => `task:needs-human-${kind}`;
export const NEEDS_HUMAN_ACTION = triage('action');
export const NEEDS_HUMAN_DECISION = triage('decision');
export const NEEDS_HUMAN_APPROVAL = triage('approval');
export const NEEDS_HUMAN_FAILURE = triage('failure');
export const TRIAGE_LABELS = Object.freeze([
  NEEDS_HUMAN_ACTION, NEEDS_HUMAN_DECISION, NEEDS_HUMAN_APPROVAL, NEEDS_HUMAN_FAILURE,
]);
// WHICH PARKS HOLD THE TASK'S LANE. An open `origin:schedule` item IS the task's
// standing item, so while one exists the generator files no further occurrence
// (`planTick` job 1) — which for a park means the task stops being scheduled at
// all until a human clears it. That is right for a `failure`: filing a queue of
// items that will break the same way helps nobody, and the silence is the signal.
// It is wrong for the other three, which are a person's inbox, not a fault in the
// task: a PR waiting to be approved, a choice waiting to be made and a secret
// waiting to be set must not also stop tomorrow's run.
//
// A park wearing NO sub-label blocks, which is what makes this safe on the way in:
// every item parked by an engine older than the sub-labels, and every kind word a
// future engine invents that this one does not know, holds the lane rather than
// silently letting a broken task keep filing work.
export const isBlockingPark = (item) =>
  hasLabel(item, NEEDS_HUMAN)
  && !hasLabel(item, NEEDS_HUMAN_ACTION)
  && !hasLabel(item, NEEDS_HUMAN_DECISION)
  && !hasLabel(item, NEEDS_HUMAN_APPROVAL);

// A kind word (from a worker's own triage marker, or a call site) to its label.
// Anything unrecognised is a `failure`: a worker that misspells its class has a
// bug, which is exactly what that lane means.
export const triageLabelFor = (kind) =>
  (TRIAGE_LABELS.includes(triage(kind)) ? triage(kind) : NEEDS_HUMAN_FAILURE);

export const OUTCOME_DONE = 'outcome:done';
// @deprecated Nothing writes this since the approval park: a run that left an
// unmerged PR no longer CLOSES as delivered, it parks at
// `task:needs-human-approval` and waits to be merged. Kept exported, kept in
// `QUEUE_LABELS`, and still read everywhere it was read — closed issues carrying
// it are stored data, and a decoder that stopped recognising it would turn every
// historical delivered run into an un-outcomed one.
export const OUTCOME_DELIVERED = 'outcome:delivered';
export const OUTCOME_OBSOLETE = 'outcome:obsolete';

// The four state labels an open item may wear. An open item wearing none of them
// and no `needs-human` is off the state machine entirely — a torn label swap's
// leavings, which the janitor repairs (DESIGN §6.2, §11).
export const STATE_LABELS = [BLOCKED, READY, EXECUTING, AGENT];

// Every label this mechanism applies, with the colour and description a bootstrap
// one-off would have given it. Ensured create-if-missing before anything is
// applied: GitHub 422s when you apply an unknown label and never creates one on
// demand, so the thing that assigns a label guarantees it first.
export const QUEUE_LABELS = [
  { name: BLOCKED, color: 'c5def5', description: 'Claudinite queue: waiting on Blocked-by and/or Not-before' },
  { name: READY, color: '0e8a16', description: 'Claudinite queue: available for an executor to pick up' },
  { name: URGENT, color: 'd93f0b', description: 'Claudinite queue: pick this before any non-urgent item' },
  { name: EXECUTING, color: 'fbca04', description: 'Claudinite queue: an executor holds the claim' },
  { name: AGENT, color: '1d76db', description: 'Claudinite queue: an agent session owns this item' },
  { name: ORIGIN_SCHEDULE, color: 'ededed', description: 'Claudinite queue: created by the generator tick at a task anchor' },
  { name: NEEDS_HUMAN, color: 'b60205', description: 'Claudinite queue: parked for a human — the one triage state' },
  { name: NEEDS_HUMAN_ACTION, color: 'b60205', description: 'Claudinite triage: a human must change something outside the code' },
  { name: NEEDS_HUMAN_DECISION, color: 'd93f0b', description: 'Claudinite triage: a human must choose what happens next' },
  { name: NEEDS_HUMAN_APPROVAL, color: '5319e7', description: 'Claudinite triage: succeeded and left an unmerged PR to approve' },
  { name: NEEDS_HUMAN_FAILURE, color: 'b60205', description: 'Claudinite triage: the run broke — diagnose and fix' },
  { name: OUTCOME_DONE, color: '0e8a16', description: 'Claudinite queue: succeeded, nothing pending' },
  { name: OUTCOME_DELIVERED, color: '5319e7', description: 'Claudinite queue: succeeded and left a live artifact the world still has to act on' },
  { name: OUTCOME_OBSOLETE, color: 'ededed', description: 'Claudinite queue: never ran — the precondition said no, or the task is gone' },
];

// GitHub hands labels back as objects on the issues API and as bare strings in
// some fixtures; accept either.
export const labelNames = (issue) =>
  (issue?.labels ?? []).map((l) => (typeof l === 'string' ? l : l?.name)).filter(Boolean);

export const hasLabel = (issue, name) => labelNames(issue).includes(name);

// Title. The optional qualifier exists ONLY for deliberately concurrent items —
// a fan-out naming its target — and it is part of the identity the same-title
// mutex reads (DESIGN §6.1). Nothing ever encodes a date here: that was the slot
// grammar, and the issue number is the identity (DESIGN §5).
export const workItemTitle = ({ pack, task, qualifier = null }) =>
  `${WORK_PREFIX} ${pack}/${task}${qualifier ? ` ${qualifier}` : ''}`;

// pack and task ids are single path segments; the qualifier is whatever follows.
const TITLE_RE = /^\[claudinite-work\]\s+([^/\s]+)\/([^/\s]+)(?:\s+(\S.*))?$/;

// The pack half is canonicalized on the way out. A work item's title is STORED
// DATA — it sits on an open GitHub issue that outlives any one converge — so items
// filed before a pack was renamed still carry the old spelling. Read literally, the
// tick would not recognise its own live item, would file a second one beside it, and
// would leave the first orphaned in the queue with nothing ever draining it.
export function parseWorkItemTitle(title) {
  const m = TITLE_RE.exec(String(title ?? '').trim());
  return m ? { pack: canonicalPackId(m[1]), task: m[2], qualifier: m[3]?.trim() || null } : null;
}

export const isWorkItemTitle = (title) => parseWorkItemTitle(title) !== null;

// --- comment markers ----------------------------------------------------------
// The three comments the protocol reads back. They are HTML comments so a human
// reading the item sees prose, and they are here — with the labels and the body
// fields — because together they ARE the item's vocabulary, the one compatibility
// surface across engine versions (DESIGN §14).
//
// The CLAIM comment carries who and when (executor identity is an unbounded set
// and must never become a label). The HANDOFF comment names the session and the
// invocation nonce. The EPISODE comment is the boundary the claim arbiter is
// scoped to: every claim before it is dead, and arbitrating over dead claims makes
// one outrank every future live claimant — the item then livelocks through reclaim
// cycles forever (F18). A reclaim, a revert and a hand re-queue each write one.
export const CLAIM_MARKER = '<!-- claudinite-claim -->';
export const HANDOFF_MARKER = '<!-- claudinite-handoff -->';
export const EPISODE_MARKER = '<!-- claudinite-episode -->';

// --- the body -----------------------------------------------------------------

export const NOT_BEFORE_FIELD = 'Not-before';
export const BLOCKED_BY_FIELD = 'Blocked-by';

// The heading the delivered-artifacts section carries in a work item body. One
// home, because it is written in three places and MATCHED when a re-entrant run
// updates the section it already wrote.
export const DELIVERED_HEADING = 'Delivered by code-work';

// The same heading as earlier renames spelled it. A live item's body still carries
// whichever word was current when its section was first written, and matching only
// today's would append a SECOND section rather than updating that one.
export const LEGACY_DELIVERED_HEADINGS = Object.freeze([
  'Delivered by prework',
  'Delivered by code_work',
]);

const NOT_BEFORE_RE = /^Not-before:[ \t]*(.*)$/m;
const BLOCKED_BY_RE = /^Blocked-by:[ \t]*(.*)$/m;

// Build a work item body. The first line is the task path — the only thing an
// executor reads to locate the worker, validated in code before anything trusts
// it. Everything behavior-defining (model, ceiling, worker content, code-work
// command) is read from the tracked task files at HEAD, never from here.
export function workItemBody({
  taskPath, notBefore = null, blockedBy = [], context = [], delivered = [], reason = null,
}) {
  const lines = [taskPath, ''];
  const fields = [];
  if (notBefore) fields.push(`${NOT_BEFORE_FIELD}: ${notBefore}`);
  if (blockedBy.length) fields.push(`${BLOCKED_BY_FIELD}: ${blockedBy.map((n) => `#${n}`).join(', ')}`);
  if (fields.length) lines.push(...fields, '');
  lines.push('Execute the Claudinite task above.');
  if (context.length) {
    lines.push(
      'The Context section below is binding scope — do not re-decide it.',
      '',
      '### Context',
      ...context.map((c) => `- ${c}`),
    );
  }
  if (reason) lines.push('', '### Why the agent is here', '', `- ${reason}`);
  if (delivered.length) lines.push('', `### ${DELIVERED_HEADING}`, '', ...delivered.map((d) => `- ${d}`));
  return lines.join('\n') + '\n';
}

// Parse an item body back into the facts the tick and the executor read. A body
// with no first line, or whose fields are absent, yields nulls — absence is
// meaningful everywhere here and is never filled in with a default.
export function parseWorkItemBody(body) {
  const text = String(body ?? '');
  const taskPath = text.split('\n').map((l) => l.trim()).find((l) => l !== '') ?? null;
  const nb = NOT_BEFORE_RE.exec(text)?.[1]?.trim() || null;
  const bb = BLOCKED_BY_RE.exec(text)?.[1] ?? '';
  const blockedBy = [...bb.matchAll(/#(\d+)/g)].map((m) => Number(m[1]));
  return { taskPath, notBefore: nb, blockedBy };
}

// The item's own `### Context` bullets, in order — the binding scope a hand-created
// item was born with. Read back rather than kept only for the agent to read,
// because an operator's PARAMETERS ride here: `create-work-item --context
// "REPOS=Alpha Beta"` is how a forced run says what it is running on, and the
// executor hands these lines to code-work as `CLAUDINITE_CONTEXT`.
//
// A section runs to the next `### ` heading or to the end of the body — the same
// bounds `withSection` writes to — and only `- ` bullets count, so the prose
// framing around a section contributes nothing.
export function parseContextLines(body) {
  const lines = String(body ?? '').split('\n');
  const at = lines.findIndex((l) => l.trim() === '### Context');
  if (at === -1) return [];
  const out = [];
  for (const line of lines.slice(at + 1)) {
    if (line.startsWith('### ')) break;
    const m = /^-[ \t]+(.*)$/.exec(line);
    if (m) out.push(m[1].trim());
  }
  return out;
}

// Fold a second set of Context lines into the first, keeping order and dropping
// exact duplicates. Both sides are real scope — the item carries what its creator
// bound it to, the precondition adds what this occurrence found — and a set-write
// from either side would drop the other's.
export const mergeContext = (...groups) => [...new Set(groups.flat().filter((l) => l && l.trim()))];

// Stamp (or clear) `Not-before` on an existing body, in place where the field is
// already present and directly under the task path otherwise. Text surgery rather
// than a rebuild: the body also carries the creating precondition's Context and
// code-work's Delivered section, which belong to whoever wrote them.
export function withNotBefore(body, iso) {
  const text = String(body ?? '');
  if (NOT_BEFORE_RE.test(text)) {
    return iso
      ? text.replace(NOT_BEFORE_RE, `${NOT_BEFORE_FIELD}: ${iso}`)
      : text.replace(/^Not-before:[ \t]*.*\n?/m, '');
  }
  if (!iso) return text;
  const lines = text.split('\n');
  const at = lines.findIndex((l) => l.trim() !== '');
  if (at === -1) return `${NOT_BEFORE_FIELD}: ${iso}\n`;
  lines.splice(at + 1, 0, '', `${NOT_BEFORE_FIELD}: ${iso}`);
  return lines.join('\n');
}

// Set a section of an item body (the Context, code-work's Delivered, the agent's Why)
// — replacing one of the same heading if it is already there, appending otherwise.
//
// REPLACING IS THE WHOLE POINT, and appending was a live bug (#879). Every standing
// item is born carrying a `### Context`, and the hand-off writes Context again — so
// an append leaves TWO sections of that name, while the session is told to read "the
// issue's Context section", singular. The one it reads first is then the tick's birth
// note and the binding scope is in the other, which fails silently whichever section
// the agent picks. It also grows: an item re-queued through hand-off twice carried a
// third.
//
// A section runs to the next `### ` heading or to the end of the body, so a replaced
// section keeps its position rather than migrating to the bottom — the body stays in
// the order a reader learned it.
// `aliases` are older spellings of the SAME heading. The section is rewritten under
// `heading`, but located by any of them, so a body written before a rename is updated
// in place instead of gaining a second section.
export function withSection(body, heading, lines, aliases = []) {
  if (!lines.length) return body;
  const text = String(body ?? '').replace(/\s*$/, '');
  const section = [`### ${heading}`, '', ...lines.map((l) => `- ${l}`)];
  const existing = text.split('\n');
  const wanted = new Set([heading, ...aliases].map((h) => `### ${h}`));
  const at = existing.findIndex((l) => wanted.has(l.trim()));
  if (at === -1) return `${text}\n\n${section.join('\n')}\n`;
  const after = existing.findIndex((l, i) => i > at && l.startsWith('### '));
  const tail = after === -1 ? [] : ['', ...existing.slice(after)];
  return `${[...existing.slice(0, at), ...section, ...tail].join('\n')}\n`;
}

content.content:
// The executor (tasks-dispatch DESIGN §6) — a pull worker over the queue. Each
// iteration: pick the next ready item, claim it by a verified lease, evaluate the
// precondition (THE only place it is ever evaluated), then on a go run code-work and
// either converge (agentless) or hand off to an agent session; on a no-go roll a
// scheduled item to its next anchor with the reason on record.
//
// An executor's whole interface is issue read/write plus the repo at HEAD, which
// is what makes it platform-agnostic: the reference deployment is a job in the
// vendored workflows (the tick's post-tick drain, and a `labeled`-event run for
// latency), but a runner anywhere with an issues-scope token qualifies. Nothing
// enumerates executors; identity is self-declared in the claim comment.
//
// The pure decisions live at the top and test with fixtures; the shell below is
// the GitHub/code-work/invocation I/O around them.

import { pathToFileURL } from 'node:url';
import { nextAnchor } from './anchors.mjs';
import {
  READY, URGENT, EXECUTING, AGENT, BLOCKED, NEEDS_HUMAN, ORIGIN_SCHEDULE,
  OUTCOME_DONE, OUTCOME_OBSOLETE, QUEUE_LABELS,
  NEEDS_HUMAN_ACTION, NEEDS_HUMAN_APPROVAL, NEEDS_HUMAN_FAILURE, triageLabelFor,
  CLAIM_MARKER, HANDOFF_MARKER, EPISODE_MARKER,
  parseWorkItemTitle, parseWorkItemBody, parseContextLines, mergeContext, withNotBefore, withSection, hasLabel, DELIVERED_HEADING, LEGACY_DELIVERED_HEADINGS } from './work-item.mjs';

// How many items one executor run may take before it stops. Small on purpose: an
// executor is code iterating a queue, and more capacity is more executors, not a
// longer loop (DESIGN §10).
export const DEFAULT_MAX_ITEMS = 3;

const titleOf = (item) => (item.title ?? '').trim();
const taskIdOf = (item) => {
  const p = parseWorkItemTitle(item.title);
  return p ? `${p.pack}/${p.task}` : null;
};

// The pick order (DESIGN §6.1): urgent first, then oldest-created, with two skip
// rules read live at pick time.
//
//  - SAME-TITLE MUTEX (S15/F6): skip an item whose exact title has another open
//    item executing or handed to an agent — one task, one execution at a time,
//    while a fan-out's distinct qualifiers still parallelize.
//  - THE `after` YIELD (S24): skip a scheduled item whose task declares `after:
//    [T]` while T's standing item is live THIS CYCLE (ready / executing / agent).
//    A rolled upstream (blocked until its next anchor: it declined this cycle)
//    does not block, and neither does one sitting `needs-human` — a broken
//    upstream must not halt its dependents indefinitely. Deliberately NOT a
//    `Blocked-by` edge: a standing item that rolls never closes, so blocked-by
//    would starve every dependent of a quiet upstream forever.
//
// `open` is every open work item; `taskAfter(id)` gives a task's declared
// upstreams as `<pack>/<task>` ids.
export function pickOrder(open = [], { taskAfter = () => [] } = {}) {
  const live = (item) => hasLabel(item, READY) || hasLabel(item, EXECUTING) || hasLabel(item, AGENT);
  const liveUpstream = (upstreamId) => open.some((o) =>
    taskIdOf(o) === upstreamId && hasLabel(o, ORIGIN_SCHEDULE) && live(o));

  return open
    .filter((i) => hasLabel(i, READY) && !hasLabel(i, NEEDS_HUMAN))
    .filter((i) => !open.some((o) => o.number !== i.number && titleOf(o) === titleOf(i)
      && (hasLabel(o, EXECUTING) || hasLabel(o, AGENT))))
    .filter((i) => {
      if (!hasLabel(i, ORIGIN_SCHEDULE)) return true;
      return !taskAfter(taskIdOf(i)).some(liveUpstream);
    })
    .sort((a, b) =>
      (hasLabel(b, URGENT) ? 1 : 0) - (hasLabel(a, URGENT) ? 1 : 0)
      || new Date(a.created_at) - new Date(b.created_at)
      || a.number - b.number);
}

// The claim comment carries WHO and WHEN — the executor id and its run URL —
// because executor identity is an unbounded set and must never become a label
// (DESIGN §4).
export const claimComment = ({ executor, runUrl, at }) =>
  `${CLAIM_MARKER}\nClaimed by executor \`${executor}\` at ${at}.${runUrl ? `\n\nRun: ${runUrl}` : ''}`;

// Who won the claim, out of an item's comments (DESIGN §6.2). Three precisions,
// each an implicit assumption made explicit:
//
//  - "EARLIEST" MEANS LOWEST COMMENT ID, never timestamp. GitHub comment
//    `created_at` has one-second granularity, so simultaneous claims tie on time;
//    comment ids are server-assigned and strictly increasing — a total order the
//    protocol gets for free. Nothing here compares runner clocks.
//  - THE ARBITER IS EPISODE-SCOPED (F18): the earliest claim SINCE the item last
//    became ready. Over an item's lifetime dead claims accumulate (every reclaim
//    and revert leaves one), and arbitrating over all of them makes a dead claim
//    outrank every future live claimant — the item then livelocks through reclaim
//    cycles forever. The reclaim / revert / re-queue comment is the boundary.
//  - THE LABEL SWAP IS NOT THE ARBITER, so a torn swap can never mint a second
//    owner; it can only leave an item with no state label, which the janitor
//    repairs.
export function claimWinner(comments = []) {
  const sorted = [...comments].sort((a, b) => a.id - b.id);
  const boundary = sorted.filter((c) => (c.body ?? '').includes(EPISODE_MARKER)).at(-1);
  const claims = sorted
    .filter((c) => (c.body ?? '').includes(CLAIM_MARKER))
    .filter((c) => !boundary || c.id > boundary.id);
  return claims[0] ?? null;
}

// After WINNING a claim, re-verify the pick filters against live state (F15). The
// filters read possibly-stale state, so two executors can pass them simultaneously
// and claim DIFFERENT items the filters should have serialized — a twin pair, or
// an upstream and its dependent. The per-item lease cannot see that: it protects
// one item, not one title. If a conflicting item now holds an EARLIER claim
// (comment id — the same arbiter the lease trusts), this executor reverts its own
// claim and moves on. Bounded, deterministic, and the earlier claim never notices.
export function conflictsWithEarlierClaim(item, myClaimId, others, { taskAfter = () => [] } = {}) {
  const upstreams = hasLabel(item, ORIGIN_SCHEDULE) ? taskAfter(taskIdOf(item)) : [];
  return others.some((o) => {
    if (o.number === item.number) return false;
    if (!(hasLabel(o, EXECUTING) || hasLabel(o, AGENT))) return false;
    const conflicting = titleOf(o) === titleOf(item)
      || (upstreams.includes(taskIdOf(o)) && hasLabel(o, ORIGIN_SCHEDULE));
    return conflicting && o.claimId != null && o.claimId < myClaimId;
  });
}

// The no-go outcome (DESIGN §6.4). A SCHEDULED item rolls — `Not-before` stamped
// with the task's next anchor, ready → blocked, the reason recorded — so the item
// itself carries "asked, declined, wakes at T" and the tick is a pure function of
// the clock and the issue list. An AD-HOC item has no next anchor to roll to, so
// it closes obsolete with the reason commented (a follow-up whose world settled on
// its own, S17).
export function noGoPlan(item, task, schedule, now, reason) {
  if (!hasLabel(item, ORIGIN_SCHEDULE)) {
    return { kind: 'close', outcome: OUTCOME_OBSOLETE, stateReason: 'not_planned', reason };
  }
  const until = nextAnchor(task.decl.frequency, schedule, now);
  return { kind: 'roll', until: until ? until.toISOString() : null, reason };
}

// --- the shell ----------------------------------------------------------------

const nowIso = () => new Date().toISOString();

// One executor run. Injected seams keep the loop testable end to end without
// GitHub, code-work subprocesses or an invocation endpoint.
export async function runExecutor({
  gh, repo, root, config, tasks, executorId, runUrl = null,
  maxItems = DEFAULT_MAX_ITEMS, now = () => new Date(),
  collectSignalsFor, runTaskCodeWork, invokeAgent, log = console.log,
}) {
  const api = await import('../github.mjs');
  const { listOpenWorkItems } = await import('./read.mjs');
  const schedule = config.taskScheduler;
  const byId = new Map(tasks.map((t) => [`${t.pack}/${t.id}`, t]));
  const taskAfter = (id) => byId.get(id)?.decl?.after ?? [];
  const done = [];

  for (let n = 0; n < maxItems; n += 1) {
    const open = await listOpenWorkItems(gh, repo);
    const candidate = pickOrder(open, { taskAfter })[0];
    if (!candidate) break;

    // --- claim: the verified lease ------------------------------------------
    await api.swapLabel(gh, repo, candidate.number, READY, EXECUTING);
    await api.comment(gh, repo, candidate.number, claimComment({
      executor: executorId, runUrl, at: nowIso(),
    }));
    const comments = await api.listComments(gh, repo, candidate.number);
    const winner = claimWinner(comments);
    const mine = [...comments]
      .sort((a, b) => a.id - b.id)
      .filter((c) => (c.body ?? '').includes(CLAIM_MARKER) && (c.body ?? '').includes(`executor \`${executorId}\``))
      .at(-1);
    if (!winner || winner.id !== mine?.id) {
      // The loser reverts nothing — the winner's labels already stand — and moves
      // on to a DIFFERENT item, read from live state on the next iteration. It
      // does strike its own claim (F24): letting go covers losing too, and a
      // claim left behind here outlives the winner's episode and becomes the
      // earliest of the NEXT one, moving the livelock one episode along.
      await strikeClaim(api, gh, repo, mine);
      log(`- #${candidate.number}: another executor holds this episode's earliest claim — moving on`);
      continue;
    }

    // --- post-claim re-verify (F15) -----------------------------------------
    const others = await withClaimIds(api, gh, repo, await listOpenWorkItems(gh, repo), candidate.number);
    if (conflictsWithEarlierClaim(candidate, winner.id, others, { taskAfter })) {
      await api.comment(gh, repo, candidate.number,
        `${EPISODE_MARKER}\nReverting this claim: a conflicting item holds an earlier claim this cycle. Returning the item to the queue.`);
      await api.swapLabel(gh, repo, candidate.number, EXECUTING, READY);
      log(`- #${candidate.number}: reverted — a conflicting item claimed earlier`);
      continue;
    }

    const outcome = await executeItem({
      api, gh, repo, root, config, schedule, byId, item: candidate, executorId,
      claim: winner, now, collectSignalsFor, runTaskCodeWork, invokeAgent, log,
    });
    done.push({ issue: candidate.number, outcome });
  }
  return done;
}

// The claim id of each live item, so the post-claim verify can compare episodes.
// One comment read per conflicting-looking item, not per item in the repo.
async function withClaimIds(api, gh, repo, items, selfNumber) {
  const out = [];
  for (const i of items) {
    if (i.number === selfNumber || !(hasLabel(i, EXECUTING) || hasLabel(i, AGENT))) { out.push(i); continue; }
    const winner = claimWinner(await api.listComments(gh, repo, i.number));
    out.push({ ...i, claimId: winner?.id ?? null });
  }
  return out;
}

// One claimed item, from validation through to a terminal state (or a hand-off).
async function executeItem({
  api, gh, repo, root, config, schedule, byId, item, executorId, claim,
  now, collectSignalsFor, runTaskCodeWork, invokeAgent, log,
}) {
  const parsed = parseWorkItemTitle(item.title);
  const { taskPath } = parseWorkItemBody(item.body);
  const id = parsed ? `${parsed.pack}/${parsed.task}` : null;
  const task = id ? byId.get(id) : null;

  // --- validate in code, before anything trusts the issue ------------------
  if (!parsed || !taskPath) {
    await converge(api, gh, repo, item.number, EXECUTING, NEEDS_HUMAN_FAILURE, claim,
      'This work item is malformed — its title or first body line does not name a task. Possible forgery; a human should look at it.');
    return 'needs-human';
  }
  if (!task) {
    await close(api, gh, repo, item.number, EXECUTING, OUTCOME_OBSOLETE, 'not_planned',
      `\`${id}\` is not a task this repo carries at HEAD (the pack may be undeclared, or the task removed). Closing obsolete.`);
    return 'obsolete';
  }
  if (task.taskPath !== taskPath) {
    await converge(api, gh, repo, item.number, EXECUTING, NEEDS_HUMAN_FAILURE, claim,
      `This item's task path (\`${taskPath}\`) is not where \`${id}\` lives at HEAD (\`${task.taskPath}\`). Not running it.`);
    return 'needs-human';
  }

  // --- the single precondition evaluation (DESIGN §6.4) --------------------
  const at = now();
  const signals = await collectSignalsFor(task, at);
  const verdict = evaluatePrecondition(task, signals, config.packConfig?.[task.pack] ?? {});
  if (verdict.run !== true) {
    const plan = noGoPlan(item, task, schedule, at, verdict.reason || 'no work');
    if (plan.kind === 'close') {
      await close(api, gh, repo, item.number, EXECUTING, OUTCOME_OBSOLETE, 'not_planned',
        `The precondition declined and this item has no anchor to roll to: ${plan.reason}`);
      return 'obsolete';
    }
    // The roll writes no comment — the `Not-before` bump IS the record, and an
    // hourly task that stays quiet would otherwise fill its own timeline (§5).
    // Which is exactly why the claim is STRUCK rather than closed by a marker
    // comment: the episode has to end here (F24) without costing a timeline entry.
    await strikeClaim(api, gh, repo, claim);
    await gh(`/repos/${repo}/issues/${item.number}`, {
      method: 'PATCH',
      body: { body: rollBody(item.body, plan.until, plan.reason, at.toISOString()) },
    });
    await api.swapLabel(gh, repo, item.number, EXECUTING, BLOCKED);
    log(`- #${item.number} ${id}: rolled to ${plan.until} — ${plan.reason}`);
    return 'rolled';
  }

  // --- code-work (unchanged contract), then converge or hand off -------------
  // The item's OWN Context is scope too, not decoration: an operator's parameters
  // (`create-work-item --context "REPOS=Alpha Beta"`) live there and nowhere else,
  // so code-work sees the union of what the item was created with and what this
  // occurrence's precondition added. Passing only the verdict's half is what made
  // a hand-created item's parameters unreachable (#974).
  const context = mergeContext(parseContextLines(item.body), verdict.context ?? []);
  if (task.decl.code_work) {
    const result = await runTaskCodeWork(task, { item, context });
    if (!result.ok) {
      // The worker's own verdict routes the park where it left one; a worker that
      // said nothing about why it failed is a `failure` — the lane that means
      // "someone reads the trace", which is the only safe default for a run whose
      // cause is unknown.
      await converge(api, gh, repo, item.number, EXECUTING, triageLabelFor(result.triage?.kind), claim,
        `Code-work failed: ${result.why}${result.triage?.detail ? `\n\nThe worker's own verdict: ${result.triage.detail}` : ''}`
        + `${result.detail ? `\n\n\`\`\`\n${result.detail}\n\`\`\`` : ''}`);
      return 'needs-human';
    }
    if (result.missingSecrets?.length) {
      await converge(api, gh, repo, item.number, EXECUTING, NEEDS_HUMAN_ACTION, claim,
        `This task declares repo Actions secrets that are not configured: ${result.missingSecrets.join(', ')}. Set them in repo settings and re-queue this item (remove the \`needs-human\` labels, add \`task:ready\`).`);
      return 'needs-human';
    }
    if (!result.agentRequested) {
      // A run that deliberately left an UNMERGED PR is not finished, it is waiting
      // on a person — so the item stays OPEN at `task:needs-human-approval` rather
      // than closing as delivered. It does not hold the task's lane while it waits
      // (`isBlockingPark`): the next occurrence is filed on schedule around it, so
      // an unreviewed PR delays nobody but its reviewer.
      if (result.openPr) {
        await converge(api, gh, repo, item.number, EXECUTING, NEEDS_HUMAN_APPROVAL, claim,
          `Code-work did this run's work and opened a PR for you to approve:\n${result.delivered.map((d) => `- ${d}`).join('\n')}`
          + `\n\nMerge or close #${result.openPr}, then close this item. This task keeps running on schedule meanwhile.`);
        return 'needs-human';
      }
      await close(api, gh, repo, item.number, EXECUTING, OUTCOME_DONE, 'completed',
        result.delivered?.length
          ? `Code-work did this run's work and left:\n${result.delivered.map((d) => `- ${d}`).join('\n')}`
          : 'Code-work did this run\'s work; no agent was needed.');
      return OUTCOME_DONE;
    }
    return handOff({ api, gh, repo, item, task, id, context, result, executorId, claim, invokeAgent, config, log });
  }

  // An agentless task with no code-work does nothing (the contract forbids it).
  if (task.decl.agent_model === 'none') {
    await converge(api, gh, repo, item.number, EXECUTING, NEEDS_HUMAN_FAILURE, claim,
      'This task is agentless but declares no code_work, so there is nothing to run — a contract-forbidden shape that reached the queue.');
    return 'needs-human';
  }
  return handOff({ api, gh, repo, item, task, id, context, result: {}, executorId, claim, invokeAgent, config, log });
}

// The roll's body edit: stamp the next anchor and keep the last reason where an
// operator reads it. The reason REPLACES the previous one — the item is a status
// line, not a log; its timeline carries the history.
// Run one task's precondition. THE only place a precondition is ever called, so a
// test that drives this drives what production drives — a precondition first
// written to take `{ signals }` passed its own direct-call test and threw on every
// real run, which is the failure this seam exists to make impossible.
//
// A throwing precondition converges to a no-go with the error as its reason: one
// task's bad verdict is that item's problem, never the executor's.
export function evaluatePrecondition(task, signals, packConfig = {}) {
  try {
    return task.decl.precondition(signals, packConfig) ?? {};
  } catch (e) {
    return { run: false, reason: `precondition threw: ${e.message}` };
  }
}

export function rollBody(body, until, reason, at) {
  const stamped = withNotBefore(body, until);
  return withSection(stamped, 'Last verdict', [
    `${at} — the precondition declined: ${reason}`,
    `Asked again at ${until}.`,
  ]);
}

// Hand off to an agent session (DESIGN §6.6). ONE call per item, ever — which is
// what lets this be as short as it is. The nonce goes on the item before the call
// and travels in the payload, so the session can prove the fire it arrived on is
// the hand-off this item recorded and stop if it is not.
async function handOff({ api, gh, repo, item, task, id, context, result, executorId, claim, invokeAgent, config, log }) {
  const nonce = `${item.number}-${Math.random().toString(36).slice(2, 10)}`;
  let body = item.body;
  if (context.length) body = withSection(body, 'Context', context);
  if (result.delivered?.length) body = withSection(body, DELIVERED_HEADING, result.delivered, LEGACY_DELIVERED_HEADINGS);
  if (result.reason) body = withSection(body, 'Why the agent is here', [result.reason]);
  await gh(`/repos/${repo}/issues/${item.number}`, { method: 'PATCH', body: { body } });

  await api.swapLabel(gh, repo, item.number, EXECUTING, AGENT);
  await api.comment(gh, repo, item.number,
    `${HANDOFF_MARKER}\nHanded off by executor \`${executorId}\` — invocation nonce \`${nonce}\`.`);

  const invocation = await invokeAgent({ task, item, nonce, config });
  if (invocation.ok) {
    await api.comment(gh, repo, item.number,
      `Agent session started${invocation.sessionUrl ? `: ${invocation.sessionUrl}` : ''}.`);
    log(`- #${item.number} ${id}: handed off${invocation.sessionId ? ` (${invocation.sessionId})` : ''}`);
    return 'agent';
  }
  if (invocation.answered) {
    // The endpoint refused, so no session exists and none will: a token, a URL or
    // a routine is wrong, and every future pick would be refused the same way.
    await converge(api, gh, repo, item.number, AGENT, NEEDS_HUMAN_ACTION, claim,
      `Could not start an agent session: ${invocation.error}\n\nNo session was started. Fix the invocation endpoint, then re-queue this item (remove the \`${NEEDS_HUMAN}\` labels, add \`${READY}\`).`);
    return 'needs-human';
  }
  // NOTHING CAME BACK, and this is the case the whole design turns on: the call
  // may have started a session. Re-queueing here is what would put two sessions on
  // one item, and converging to triage would kill a run that is very possibly
  // alive. So the item STAYS with the agent and says the outcome is unknown —
  // whichever way it went is then settled by a rule that already exists: a session
  // that started converges the item, and one that never did leaves the item silent
  // until the janitor's agent leash sweeps it to triage.
  await api.comment(gh, repo, item.number,
    `The agent invocation got no answer: ${invocation.error}\n\n`
    + 'The session may or may not have started, so nothing here re-tries it — a second call could put two sessions on this item. '
    + `If a session did start it will converge this item; if it did not, the janitor's agent leash brings this item to \`${NEEDS_HUMAN}\` within a few hours.`);
  log(`! #${item.number} ${id}: invocation unanswered — left with the agent, leash decides — ${invocation.error}`);
  return 'unknown';
}

// LETTING GO OF AN OPEN ITEM KILLS YOUR CLAIM (DESIGN §6.2, F24). An executor
// that stops owning an item without closing it — the roll, and every
// `needs-human` park — strikes its own claim by appending the episode marker to
// it. `claimWinner` already treats the last marker as the boundary, so a struck
// claim stops outranking anything and the next claimant wins on its first try.
//
// APPENDING rather than commenting is what lets the roll stay silent (§5): an
// hourly task that declines every hour adds no timeline entry. A successful
// hand-off deliberately does NOT strike — the episode is still live, owned by the
// agent session — and neither does a close, since nothing re-claims a closed item.
//
// Struck BEFORE the label swap, so the crash window degrades the safe way: an
// executor that dies between the two leaves the item `task:executing` with a
// spent claim, which the tick's leash reclaim already recovers. Striking after
// would leave exactly the state this fixes — parked, re-queued by a human, and
// unclaimable forever.
async function strikeClaim(api, gh, repo, claim) {
  if (!claim || (claim.body ?? '').includes(EPISODE_MARKER)) return;
  await api.editComment(gh, repo, claim.id,
    `${claim.body}\n\n${EPISODE_MARKER}\nThis claim is spent — the executor released this item without closing it.`);
}

// Every exit converges the item exactly once, with one comment saying what
// happened — the terminal-state discipline the incidents bought. The claim sits
// before the body so every state argument is grouped ahead of the prose.
// Park an item for a human. BOTH labels, always: `needs-human` is the state every
// guard and sweep reads, `triage` is what the human is being asked for.
async function converge(api, gh, repo, number, from, triage, claim, body) {
  await strikeClaim(api, gh, repo, claim);
  await api.comment(gh, repo, number, body);
  await api.swapLabel(gh, repo, number, from, NEEDS_HUMAN);
  await api.addLabel(gh, repo, number, triage);
}

async function close(api, gh, repo, number, from, outcome, stateReason, body) {
  await api.comment(gh, repo, number, body);
  await api.removeLabel(gh, repo, number, from);
  await api.addLabel(gh, repo, number, outcome);
  await api.closeIssue(gh, repo, number, stateReason);
}

// --- CLI ----------------------------------------------------------------------

async function main() {
  const { makeGh, actionRepoContext } = await import('../signals/gh.mjs');
  const { discoverTasks } = await import('../discover.mjs');
  const { loadConfig, isDormant } = await import('../../checks/helpers/repo-context.mjs');
  const { ensureLabels } = await import('../github.mjs');
  const { collectSignalsForTask } = await import('./signals.mjs');
  const { codeWorkRunner } = await import('./code-work-run.mjs');
  const { agentInvoker } = await import('./invoke.mjs');

  const root = process.cwd();
  const { repo, defaultBranch } = actionRepoContext();
  if (!repo) { console.error('GITHUB_REPOSITORY not set — not in an Actions context'); process.exit(1); }
  const config = loadConfig(root);

  console.log('## Claudinite executor\n');
  if (isDormant(config)) {
    console.log('- this project declares itself dormant — nothing is picked up');
    return;
  }

  const gh = makeGh();
  const { tasks, errors } = await discoverTasks(root, config);
  for (const e of errors) console.log(`! ${e.what}`);
  await ensureLabels(gh, repo, QUEUE_LABELS);

  const runUrl = process.env.GITHUB_RUN_ID
    ? `${process.env.GITHUB_SERVER_URL ?? 'https://github.com'}/${repo}/actions/runs/${process.env.GITHUB_RUN_ID}`
    : null;

  const done = await runExecutor({
    gh, repo, root, config, tasks,
    executorId: process.env.CLAUDINITE_EXECUTOR_ID || `actions-${process.env.GITHUB_RUN_ID ?? 'local'}`,
    runUrl,
    maxItems: Number(process.env.CLAUDINITE_MAX_ITEMS) || DEFAULT_MAX_ITEMS,
    collectSignalsFor: collectSignalsForTask({ gh, repo, root, config, defaultBranch }),
    runTaskCodeWork: codeWorkRunner({ root, repo, defaultBranch }),
    invokeAgent: agentInvoker({ repo, config }),
  });

  console.log(done.length
    ? done.map((d) => `- #${d.issue}: ${d.outcome}`).join('\n')
    : '- nothing ready to pick up');
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  main().catch((e) => { console.error(e); process.exit(1); });
}

toolUseResult.stdout:
// The executor (tasks-dispatch DESIGN §6) — a pull worker over the queue. Each
// iteration: pick the next ready item, claim it by a verified lease, evaluate the
// precondition (THE only place it is ever evaluated), then on a go run code-work and
// either converge (agentless) or hand off to an agent session; on a no-go roll a
// scheduled item to its next anchor with the reason on record.
//
// An executor's whole interface is issue read/write plus the repo at HEAD, which
// is what makes it platform-agnostic: the reference deployment is a job in the
// vendored workflows (the tick's post-tick drain, and a `labeled`-event run for
// latency), but a runner anywhere with an issues-scope token qualifies. Nothing
// enumerates executors; identity is self-declared in the claim comment.
//
// The pure decisions live at the top and test with fixtures; the shell below is
// the GitHub/code-work/invocation I/O around them.

import { pathToFileURL } from 'node:url';
import { nextAnchor } from './anchors.mjs';
import {
  READY, URGENT, EXECUTING, AGENT, BLOCKED, NEEDS_HUMAN, ORIGIN_SCHEDULE,
  OUTCOME_DONE, OUTCOME_OBSOLETE, QUEUE_LABELS,
  NEEDS_HUMAN_ACTION, NEEDS_HUMAN_APPROVAL, NEEDS_HUMAN_FAILURE, triageLabelFor,
  CLAIM_MARKER, HANDOFF_MARKER, EPISODE_MARKER,
  parseWorkItemTitle, parseWorkItemBody, parseContextLines, mergeContext, withNotBefore, withSection, hasLabel, DELIVERED_HEADING, LEGACY_DELIVERED_HEADINGS } from './work-item.mjs';

// How many items one executor run may take before it stops. Small on purpose: an
// executor is code iterating a queue, and more capacity is more executors, not a
// longer loop (DESIGN §10).
export const DEFAULT_MAX_ITEMS = 3;

const titleOf = (item) => (item.title ?? '').trim();
const taskIdOf = (item) => {
  const p = parseWorkItemTitle(item.title);
  return p ? `${p.pack}/${p.task}` : null;
};

// The pick order (DESIGN §6.1): urgent first, then oldest-created, with two skip
// rules read live at pick time.
//
//  - SAME-TITLE MUTEX (S15/F6): skip an item whose exact title has another open
//    item executing or handed to an agent — one task, one execution at a time,
//    while a fan-out's distinct qualifiers still parallelize.
//  - THE `after` YIELD (S24): skip a scheduled item whose task declares `after:
//    [T]` while T's standing item is live THIS CYCLE (ready / executing / agent).
//    A rolled upstream (blocked until its next anchor: it declined this cycle)
//    does not block, and neither does one sitting `needs-human` — a broken
//    upstream must not halt its dependents indefinitely. Deliberately NOT a
//    `Blocked-by` edge: a standing item that rolls never closes, so blocked-by
//    would starve every dependent of a quiet upstream forever.
//
// `open` is every open work item; `taskAfter(id)` gives a task's declared
// upstreams as `<pack>/<task>` ids.
export function pickOrder(open = [], { taskAfter = () => [] } = {}) {
  const live = (item) => hasLabel(item, READY) || hasLabel(item, EXECUTING) || hasLabel(item, AGENT);
  const liveUpstream = (upstreamId) => open.some((o) =>
    taskIdOf(o) === upstreamId && hasLabel(o, ORIGIN_SCHEDULE) && live(o));

  return open
    .filter((i) => hasLabel(i, READY) && !hasLabel(i, NEEDS_HUMAN))
    .filter((i) => !open.some((o) => o.number !== i.number && titleOf(o) === titleOf(i)
      && (hasLabel(o, EXECUTING) || hasLabel(o, AGENT))))
    .filter((i) => {
      if (!hasLabel(i, ORIGIN_SCHEDULE)) return true;
      return !taskAfter(taskIdOf(i)).some(liveUpstream);
    })
    .sort((a, b) =>
      (hasLabel(b, URGENT) ? 1 : 0) - (hasLabel(a, URGENT) ? 1 : 0)
      || new Date(a.created_at) - new Date(b.created_at)
      || a.number - b.number);
}

// The claim comment carries WHO and WHEN — the executor id and its run URL —
// because executor identity is an unbounded set and must never become a label
// (DESIGN §4).
export const claimComment = ({ executor, runUrl, at }) =>
  `${CLAIM_MARKER}\nClaimed by executor \`${executor}\` at ${at}.${runUrl ? `\n\nRun: ${runUrl}` : ''}`;

// Who won the claim, out of an item's comments (DESIGN §6.2). Three precisions,
// each an implicit assumption made explicit:
//
//  - "EARLIEST" MEANS LOWEST COMMENT ID, never timestamp. GitHub comment
//    `created_at` has one-second granularity, so simultaneous claims tie on time;
//    comment ids are server-assigned and strictly increasing — a total order the
//    protocol gets for free. Nothing here compares runner clocks.
//  - THE ARBITER IS EPISODE-SCOPED (F18): the earliest claim SINCE the item last
//    became ready. Over an item's lifetime dead claims accumulate (every reclaim
//    and revert leaves one), and arbitrating over all of them makes a dead claim
//    outrank every future live claimant — the item then livelocks through reclaim
//    cycles forever. The reclaim / revert / re-queue comment is the boundary.
//  - THE LABEL SWAP IS NOT THE ARBITER, so a torn swap can never mint a second
//    owner; it can only leave an item with no state label, which the janitor
//    repairs.
export function claimWinner(comments = []) {
  const sorted = [...comments].sort((a, b) => a.id - b.id);
  const boundary = sorted.filter((c) => (c.body ?? '').includes(EPISODE_MARKER)).at(-1);
  const claims = sorted
    .filter((c) => (c.body ?? '').includes(CLAIM_MARKER))
    .filter((c) => !boundary || c.id > boundary.id);
  return claims[0] ?? null;
}

// After WINNING a claim, re-verify the pick filters against live state (F15). The
// filters read possibly-stale state, so two executors can pass them simultaneously
// and claim DIFFERENT items the filters should have serialized — a twin pair, or
// an upstream and its dependent. The per-item lease cannot see that: it protects
// one item, not one title. If a conflicting item now holds an EARLIER claim
// (comment id — the same arbiter the lease trusts), this executor reverts its own
// claim and moves on. Bounded, deterministic, and the earlier claim never notices.
export function conflictsWithEarlierClaim(item, myClaimId, others, { taskAfter = () => [] } = {}) {
  const upstreams = hasLabel(item, ORIGIN_SCHEDULE) ? taskAfter(taskIdOf(item)) : [];
  return others.some((o) => {
    if (o.number === item.number) return false;
    if (!(hasLabel(o, EXECUTING) || hasLabel(o, AGENT))) return false;
    const conflicting = titleOf(o) === titleOf(item)
      || (upstreams.includes(taskIdOf(o)) && hasLabel(o, ORIGIN_SCHEDULE));
    return conflicting && o.claimId != null && o.claimId < myClaimId;
  });
}

// The no-go outcome (DESIGN §6.4). A SCHEDULED item rolls — `Not-before` stamped
// with the task's next anchor, ready → blocked, the reason recorded — so the item
// itself carries "asked, declined, wakes at T" and the tick is a pure function of
// the clock and the issue list. An AD-HOC item has no next anchor to roll to, so
// it closes obsolete with the reason commented (a follow-up whose world settled on
// its own, S17).
export function noGoPlan(item, task, schedule, now, reason) {
  if (!hasLabel(item, ORIGIN_SCHEDULE)) {
    return { kind: 'close', outcome: OUTCOME_OBSOLETE, stateReason: 'not_planned', reason };
  }
  const until = nextAnchor(task.decl.frequency, schedule, now);
  return { kind: 'roll', until: until ? until.toISOString() : null, reason };
}

// --- the shell ----------------------------------------------------------------

const nowIso = () => new Date().toISOString();

// One executor run. Injected seams keep the loop testable end to end without
// GitHub, code-work subprocesses or an invocation endpoint.
export async function runExecutor({
  gh, repo, root, config, tasks, executorId, runUrl = null,
  maxItems = DEFAULT_MAX_ITEMS, now = () => new Date(),
  collectSignalsFor, runTaskCodeWork, invokeAgent, log = console.log,
}) {
  const api = await import('../github.mjs');
  const { listOpenWorkItems } = await import('./read.mjs');
  const schedule = config.taskScheduler;
  const byId = new Map(tasks.map((t) => [`${t.pack}/${t.id}`, t]));
  const taskAfter = (id) => byId.get(id)?.decl?.after ?? [];
  const done = [];

  for (let n = 0; n < maxItems; n += 1) {
    const open = await listOpenWorkItems(gh, repo);
    const candidate = pickOrder(open, { taskAfter })[0];
    if (!candidate) break;

    // --- claim: the verified lease ------------------------------------------
    await api.swapLabel(gh, repo, candidate.number, READY, EXECUTING);
    await api.comment(gh, repo, candidate.number, claimComment({
      executor: executorId, runUrl, at: nowIso(),
    }));
    const comments = await api.listComments(gh, repo, candidate.number);
    const winner = claimWinner(comments);
    const mine = [...comments]
      .sort((a, b) => a.id - b.id)
      .filter((c) => (c.body ?? '').includes(CLAIM_MARKER) && (c.body ?? '').includes(`executor \`${executorId}\``))
      .at(-1);
    if (!winner || winner.id !== mine?.id) {
      // The loser reverts nothing — the winner's labels already stand — and moves
      // on to a DIFFERENT item, read from live state on the next iteration. It
      // does strike its own claim (F24): letting go covers losing too, and a
      // claim left behind here outlives the winner's episode and becomes the
      // earliest of the NEXT one, moving the livelock one episode along.
      await strikeClaim(api, gh, repo, mine);
      log(`- #${candidate.number}: another executor holds this episode's earliest claim — moving on`);
      continue;
    }

    // --- post-claim re-verify (F15) -----------------------------------------
    const others = await withClaimIds(api, gh, repo, await listOpenWorkItems(gh, repo), candidate.number);
    if (conflictsWithEarlierClaim(candidate, winner.id, others, { taskAfter })) {
      await api.comment(gh, repo, candidate.number,
        `${EPISODE_MARKER}\nReverting this claim: a conflicting item holds an earlier claim this cycle. Returning the item to the queue.`);
      await api.swapLabel(gh, repo, candidate.number, EXECUTING, READY);
      log(`- #${candidate.number}: reverted — a conflicting item claimed earlier`);
      continue;
    }

    const outcome = await executeItem({
      api, gh, repo, root, config, schedule, byId, item: candidate, executorId,
      claim: winner, now, collectSignalsFor, runTaskCodeWork, invokeAgent, log,
    });
    done.push({ issue: candidate.number, outcome });
  }
  return done;
}

// The claim id of each live item, so the post-claim verify can compare episodes.
// One comment read per conflicting-looking item, not per item in the repo.
async function withClaimIds(api, gh, repo, items, selfNumber) {
  const out = [];
  for (const i of items) {
    if (i.number === selfNumber || !(hasLabel(i, EXECUTING) || hasLabel(i, AGENT))) { out.push(i); continue; }
    const winner = claimWinner(await api.listComments(gh, repo, i.number));
    out.push({ ...i, claimId: winner?.id ?? null });
  }
  return out;
}

// One claimed item, from validation through to a terminal state (or a hand-off).
async function executeItem({
  api, gh, repo, root, config, schedule, byId, item, executorId, claim,
  now, collectSignalsFor, runTaskCodeWork, invokeAgent, log,
}) {
  const parsed = parseWorkItemTitle(item.title);
  const { taskPath } = parseWorkItemBody(item.body);
  const id = parsed ? `${parsed.pack}/${parsed.task}` : null;
  const task = id ? byId.get(id) : null;

  // --- validate in code, before anything trusts the issue ------------------
  if (!parsed || !taskPath) {
    await converge(api, gh, repo, item.number, EXECUTING, NEEDS_HUMAN_FAILURE, claim,
      'This work item is malformed — its title or first body line does not name a task. Possible forgery; a human should look at it.');
    return 'needs-human';
  }
  if (!task) {
    await close(api, gh, repo, item.number, EXECUTING, OUTCOME_OBSOLETE, 'not_planned',
      `\`${id}\` is not a task this repo carries at HEAD (the pack may be undeclared, or the task removed). Closing obsolete.`);
    return 'obsolete';
  }
  if (task.taskPath !== taskPath) {
    await converge(api, gh, repo, item.number, EXECUTING, NEEDS_HUMAN_FAILURE, claim,
      `This item's task path (\`${taskPath}\`) is not where \`${id}\` lives at HEAD (\`${task.taskPath}\`). Not running it.`);
    return 'needs-human';
  }

  // --- the single precondition evaluation (DESIGN §6.4) --------------------
  const at = now();
  const signals = await collectSignalsFor(task, at);
  const verdict = evaluatePrecondition(task, signals, config.packConfig?.[task.pack] ?? {});
  if (verdict.run !== true) {
    const plan = noGoPlan(item, task, schedule, at, verdict.reason || 'no work');
    if (plan.kind === 'close') {
      await close(api, gh, repo, item.number, EXECUTING, OUTCOME_OBSOLETE, 'not_planned',
        `The precondition declined and this item has no anchor to roll to: ${plan.reason}`);
      return 'obsolete';
    }
    // The roll writes no comment — the `Not-before` bump IS the record, and an
    // hourly task that stays quiet would otherwise fill its own timeline (§5).
    // Which is exactly why the claim is STRUCK rather than closed by a marker
    // comment: the episode has to end here (F24) without costing a timeline entry.
    await strikeClaim(api, gh, repo, claim);
    await gh(`/repos/${repo}/issues/${item.number}`, {
      method: 'PATCH',
      body: { body: rollBody(item.body, plan.until, plan.reason, at.toISOString()) },
    });
    await api.swapLabel(gh, repo, item.number, EXECUTING, BLOCKED);
    log(`- #${item.number} ${id}: rolled to ${plan.until} — ${plan.reason}`);
    return 'rolled';
  }

  // --- code-work (unchanged contract), then converge or hand off -------------
  // The item's OWN Context is scope too, not decoration: an operator's parameters
  // (`create-work-item --context "REPOS=Alpha Beta"`) live there and nowhere else,
  // so code-work sees the union of what the item was created with and what this
  // occurrence's precondition added. Passing only the verdict's half is what made
  // a hand-created item's parameters unreachable (#974).
  const context = mergeContext(parseContextLines(item.body), verdict.context ?? []);
  if (task.decl.code_work) {
    const result = await runTaskCodeWork(task, { item, context });
    if (!result.ok) {
      // The worker's own verdict routes the park where it left one; a worker that
      // said nothing about why it failed is a `failure` — the lane that means
      // "someone reads the trace", which is the only safe default for a run whose
      // cause is unknown.
      await converge(api, gh, repo, item.number, EXECUTING, triageLabelFor(result.triage?.kind), claim,
        `Code-work failed: ${result.why}${result.triage?.detail ? `\n\nThe worker's own verdict: ${result.triage.detail}` : ''}`
        + `${result.detail ? `\n\n\`\`\`\n${result.detail}\n\`\`\`` : ''}`);
      return 'needs-human';
    }
    if (result.missingSecrets?.length) {
      await converge(api, gh, repo, item.number, EXECUTING, NEEDS_HUMAN_ACTION, claim,
        `This task declares repo Actions secrets that are not configured: ${result.missingSecrets.join(', ')}. Set them in repo settings and re-queue this item (remove the \`needs-human\` labels, add \`task:ready\`).`);
      return 'needs-human';
    }
    if (!result.agentRequested) {
      // A run that deliberately left an UNMERGED PR is not finished, it is waiting
      // on a person — so the item stays OPEN at `task:needs-human-approval` rather
      // than closing as delivered. It does not hold the task's lane while it waits
      // (`isBlockingPark`): the next occurrence is filed on schedule around it, so
      // an unreviewed PR delays nobody but its reviewer.
      if (result.openPr) {
        await converge(api, gh, repo, item.number, EXECUTING, NEEDS_HUMAN_APPROVAL, claim,
          `Code-work did this run's work and opened a PR for you to approve:\n${result.delivered.map((d) => `- ${d}`).join('\n')}`
          + `\n\nMerge or close #${result.openPr}, then close this item. This task keeps running on schedule meanwhile.`);
        return 'needs-human';
      }
      await close(api, gh, repo, item.number, EXECUTING, OUTCOME_DONE, 'completed',
        result.delivered?.length
          ? `Code-work did this run's work and left:\n${result.delivered.map((d) => `- ${d}`).join('\n')}`
          : 'Code-work did this run\'s work; no agent was needed.');
      return OUTCOME_DONE;
    }
    return handOff({ api, gh, repo, item, task, id, context, result, executorId, claim, invokeAgent, config, log });
  }

  // An agentless task with no code-work does nothing (the contract forbids it).
  if (task.decl.agent_model === 'none') {
    await converge(api, gh, repo, item.number, EXECUTING, NEEDS_HUMAN_FAILURE, claim,
      'This task is agentless but declares no code_work, so there is nothing to run — a contract-forbidden shape that reached the queue.');
    return 'needs-human';
  }
  return handOff({ api, gh, repo, item, task, id, context, result: {}, executorId, claim, invokeAgent, config, log });
}

// The roll's body edit: stamp the next anchor and keep the last reason where an
// operator reads it. The reason REPLACES the previous one — the item is a status
// line, not a log; its timeline carries the history.
// Run one task's precondition. THE only place a precondition is ever called, so a
// test that drives this drives what production drives — a precondition first
// written to take `{ signals }` passed its own direct-call test and threw on every
// real run, which is the failure this seam exists to make impossible.
//
// A throwing precondition converges to a no-go with the error as its reason: one
// task's bad verdict is that item's problem, never the executor's.
export function evaluatePrecondition(task, signals, packConfig = {}) {
  try {
    return task.decl.precondition(signals, packConfig) ?? {};
  } catch (e) {
    return { run: false, reason: `precondition threw: ${e.message}` };
  }
}

export function rollBody(body, until, reason, at) {
  const stamped = withNotBefore(body, until);
  return withSection(stamped, 'Last verdict', [
    `${at} — the precondition declined: ${reason}`,
    `Asked again at ${until}.`,
  ]);
}

// Hand off to an agent session (DESIGN §6.6). ONE call per item, ever — which is
// what lets this be as short as it is. The nonce goes on the item before the call
// and travels in the payload, so the session can prove the fire it arrived on is
// the hand-off this item recorded and stop if it is not.
async function handOff({ api, gh, repo, item, task, id, context, result, executorId, claim, invokeAgent, config, log }) {
  const nonce = `${item.number}-${Math.random().toString(36).slice(2, 10)}`;
  let body = item.body;
  if (context.length) body = withSection(body, 'Context', context);
  if (result.delivered?.length) body = withSection(body, DELIVERED_HEADING, result.delivered, LEGACY_DELIVERED_HEADINGS);
  if (result.reason) body = withSection(body, 'Why the agent is here', [result.reason]);
  await gh(`/repos/${repo}/issues/${item.number}`, { method: 'PATCH', body: { body } });

  await api.swapLabel(gh, repo, item.number, EXECUTING, AGENT);
  await api.comment(gh, repo, item.number,
    `${HANDOFF_MARKER}\nHanded off by executor \`${executorId}\` — invocation nonce \`${nonce}\`.`);

  const invocation = await invokeAgent({ task, item, nonce, config });
  if (invocation.ok) {
    await api.comment(gh, repo, item.number,
      `Agent session started${invocation.sessionUrl ? `: ${invocation.sessionUrl}` : ''}.`);
    log(`- #${item.number} ${id}: handed off${invocation.sessionId ? ` (${invocation.sessionId})` : ''}`);
    return 'agent';
  }
  if (invocation.answered) {
    // The endpoint refused, so no session exists and none will: a token, a URL or
    // a routine is wrong, and every future pick would be refused the same way.
    await converge(api, gh, repo, item.number, AGENT, NEEDS_HUMAN_ACTION, claim,
      `Could not start an agent session: ${invocation.error}\n\nNo session was started. Fix the invocation endpoint, then re-queue this item (remove the \`${NEEDS_HUMAN}\` labels, add \`${READY}\`).`);
    return 'needs-human';
  }
  // NOTHING CAME BACK, and this is the case the whole design turns on: the call
  // may have started a session. Re-queueing here is what would put two sessions on
  // one item, and converging to triage would kill a run that is very possibly
  // alive. So the item STAYS with the agent and says the outcome is unknown —
  // whichever way it went is then settled by a rule that already exists: a session
  // that started converges the item, and one that never did leaves the item silent
  // until the janitor's agent leash sweeps it to triage.
  await api.comment(gh, repo, item.number,
    `The agent invocation got no answer: ${invocation.error}\n\n`
    + 'The session may or may not have started, so nothing here re-tries it — a second call could put two sessions on this item. '
    + `If a session did start it will converge this item; if it did not, the janitor's agent leash brings this item to \`${NEEDS_HUMAN}\` within a few hours.`);
  log(`! #${item.number} ${id}: invocation unanswered — left with the agent, leash decides — ${invocation.error}`);
  return 'unknown';
}

// LETTING GO OF AN OPEN ITEM KILLS YOUR CLAIM (DESIGN §6.2, F24). An executor
// that stops owning an item without closing it — the roll, and every
// `needs-human` park — strikes its own claim by appending the episode marker to
// it. `claimWinner` already treats the last marker as the boundary, so a struck
// claim stops outranking anything and the next claimant wins on its first try.
//
// APPENDING rather than commenting is what lets the roll stay silent (§5): an
// hourly task that declines every hour adds no timeline entry. A successful
// hand-off deliberately does NOT strike — the episode is still live, owned by the
// agent session — and neither does a close, since nothing re-claims a closed item.
//
// Struck BEFORE the label swap, so the crash window degrades the safe way: an
// executor that dies between the two leaves the item `task:executing` with a
// spent claim, which the tick's leash reclaim already recovers. Striking after
// would leave exactly the state this fixes — parked, re-queued by a human, and
// unclaimable forever.
async function strikeClaim(api, gh, repo, claim) {
  if (!claim || (claim.body ?? '').includes(EPISODE_MARKER)) return;
  await api.editComment(gh, repo, claim.id,
    `${claim.body}\n\n${EPISODE_MARKER}\nThis claim is spent — the executor released this item without closing it.`);
}

// Every exit converges the item exactly once, with one comment saying what
// happened — the terminal-state discipline the incidents bought. The claim sits
// before the body so every state argument is grouped ahead of the prose.
// Park an item for a human. BOTH labels, always: `needs-human` is the state every
// guard and sweep reads, `triage` is what the human is being asked for.
async function converge(api, gh, repo, number, from, triage, claim, body) {
  await strikeClaim(api, gh, repo, claim);
  await api.comment(gh, repo, number, body);
  await api.swapLabel(gh, repo, number, from, NEEDS_HUMAN);
  await api.addLabel(gh, repo, number, triage);
}

async function close(api, gh, repo, number, from, outcome, stateReason, body) {
  await api.comment(gh, repo, number, body);
  await api.removeLabel(gh, repo, number, from);
  await api.addLabel(gh, repo, number, outcome);
  await api.closeIssue(gh, repo, number, stateReason);
}

// --- CLI ----------------------------------------------------------------------

async function main() {
  const { makeGh, actionRepoContext } = await import('../signals/gh.mjs');
  const { discoverTasks } = await import('../discover.mjs');
  const { loadConfig, isDormant } = await import('../../checks/helpers/repo-context.mjs');
  const { ensureLabels } = await import('../github.mjs');
  const { collectSignalsForTask } = await import('./signals.mjs');
  const { codeWorkRunner } = await import('./code-work-run.mjs');
  const { agentInvoker } = await import('./invoke.mjs');

  const root = process.cwd();
  const { repo, defaultBranch } = actionRepoContext();
  if (!repo) { console.error('GITHUB_REPOSITORY not set — not in an Actions context'); process.exit(1); }
  const config = loadConfig(root);

  console.log('## Claudinite executor\n');
  if (isDormant(config)) {
    console.log('- this project declares itself dormant — nothing is picked up');
    return;
  }

  const gh = makeGh();
  const { tasks, errors } = await discoverTasks(root, config);
  for (const e of errors) console.log(`! ${e.what}`);
  await ensureLabels(gh, repo, QUEUE_LABELS);

  const runUrl = process.env.GITHUB_RUN_ID
    ? `${process.env.GITHUB_SERVER_URL ?? 'https://github.com'}/${repo}/actions/runs/${process.env.GITHUB_RUN_ID}`
    : null;

  const done = await runExecutor({
    gh, repo, root, config, tasks,
    executorId: process.env.CLAUDINITE_EXECUTOR_ID || `actions-${process.env.GITHUB_RUN_ID ?? 'local'}`,
    runUrl,
    maxItems: Number(process.env.CLAUDINITE_MAX_ITEMS) || DEFAULT_MAX_ITEMS,
    collectSignalsFor: collectSignalsForTask({ gh, repo, root, config, defaultBranch }),
    runTaskCodeWork: codeWorkRunner({ root, repo, defaultBranch }),
    invokeAgent: agentInvoker({ repo, config }),
  });

  console.log(done.length
    ? done.map((d) => `- #${d.issue}: ${d.outcome}`).join('\n')
    : '- nothing ready to pick up');
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  main().catch((e) => { console.error(e); process.exit(1); });
}

