  // notification) declares `needs-human`, and every recovery path that would
  // re-execute it — the leash reclaim, the hand-off retry — converges to triage
  // instead: at-most-once plus a human.
  if (decl.on_interrupt !== undefined && !INTERRUPT_POLICIES.includes(decl.on_interrupt)) {
    bad(`"on_interrupt" ${JSON.stringify(decl.on_interrupt)} is not a legal policy`, `set one of: ${INTERRUPT_POLICIES.join(', ')} (default "requeue")`);
  }

  // `invocation_endpoint` — a NAME, never a URL (DESIGN §12). The repo's config
  // maps the name to the URL and to the name of the Actions secret holding its
  // token, so no vendored pack file carries deployment detail or anything adjacent
  // to a credential. This is also what replaces session_scope: reach is a property
  // of which endpoint a task names.
  if (decl.invocation_endpoint !== undefined
      && !(typeof decl.invocation_endpoint === 'string' && /^[a-z0-9]+(-[a-z0-9]+)*$/.test(decl.invocation_endpoint))) {
    bad('"invocation_endpoint" is not a kebab-case endpoint name', 'name a key from the repo\'s taskScheduler.endpoints map, e.g. "fleet" — never a URL');
  }

  // The repo Actions secrets this task needs configured (DESIGN §9). Purely
  // DECLARATIVE — like a pack's adoption `questions`, its job is to drive the ask
  // (adoption interactively, the scheduler by owner issue), not to gate anything
  // here. So the only shape asserted is "a list of names"; whether the repo has
  // actually configured them is a fact about the repo, answered where the secrets
  // bundle is readable, never at author time.
  if (decl.required_secrets !== undefined
      && !(Array.isArray(decl.required_secrets) && decl.required_secrets.every((s) => typeof s === 'string' && s.trim() !== ''))) {
    bad('"required_secrets" is not an array of secret names', 'list the repo Actions secret names this task needs, e.g. ["SOME_API_KEY"]');
  }

  // Execution bound (task-code-work DESIGN §2, §6) — an agentic task MUST
  // declare a positive-integer agent_execution_timeout. There is always a bound
  // on an agentic run; enforcement is best-effort (the executor surfaces the
  // value to the subagent). A `none` task runs no agent, so it needs none.
  if (MODEL_FAMILIES.includes(decl.agent_model) && decl.agent_model !== 'none' && !isPositiveInt(decl.agent_execution_timeout)) {
    bad('an agentic task (agent_model !== "none") declares no positive-integer "agent_execution_timeout"', 'add "agent_execution_timeout": the seconds bounding the agentic run — generous; extreme protection, not a scheduling knob');
  }

  // An agentless task (agent_model: none) runs no agent, so its ONLY work is
  // code-work — a `none` task with no code-work does nothing (DESIGN §4, retiring
  // the in-process inline path). Require the command.
  if (decl.agent_model === 'none' && decl.code_work === undefined) {
    bad('an agentless task (agent_model: "none") declares no "code_work"', 'add "code_work" (a none task does its work in that subprocess) — or give the task an agent_model');
  }

  return problems;
}
// Task discovery for the scheduler (per-project-scheduling DESIGN §3.2). One
// uniform scan of every ACTIVE pack's `tasks/<name>/task.mjs`, activation-gated
// by the repo's `packs` declaration exactly like checks and skills. Reuses the
// pack registry so the same scan works across all three layouts without knowing
// any of them: canon packs at `packs/`, a consumer's vendored canon at
// `.claudinite/shared/packs/`, and local packs at `.claudinite/local/packs/`
// (each pack carries its own resolved `dir`).
//
// Frequency filtering is deliberately NOT done here — discover returns every
// active, well-formed task; the tick intersects them with the current anchors
// (queue/anchors.mjs). Keeping the two apart keeps each pure and separately
// testable. A task whose task.mjs fails to import or violates the declaration
// contract is dropped into `errors` (fail-soft, per-task), never sinking the
// scan.

import { readdirSync, existsSync } from 'node:fs';
import { join, relative } from 'node:path';
import { pathToFileURL } from 'node:url';
import { loadPacks, isActive } from '../pack_loader/pack-registry.mjs';
import { normalizeTaskDeclaration, validateTaskDeclaration } from './task-contract.mjs';

// Discover every task the repo's active packs contribute. Returns
// `{ tasks, errors }` where each task is
// `{ pack, id, taskDir, taskPath, decl }` — `taskPath` is the repo-relative
// path to the worker file's directory's task.md (the work item's first
// line), `decl` the validated declaration.
export async function discoverTasks(root, config) {
  const errors = [];
  const packs = await loadPacks({ localRoot: root });
  const active = packs.filter((p) => isActive(p, config));

  const tasks = [];
  for (const pack of active) {
    const tasksRoot = join(pack.dir, 'tasks');
    if (!existsSync(tasksRoot)) continue;
    let names;
    try {
      names = readdirSync(tasksRoot, { withFileTypes: true })
        .filter((d) => d.isDirectory()).map((d) => d.name).sort();
    } catch (e) {
      errors.push({ pack: pack.id, what: `${pack.id}'s tasks/ is not a readable directory: ${e.message}`, fix: `make ${relative(root, tasksRoot)} a directory (or remove it)` });
      continue;
    }
    for (const name of names) {
      const taskDir = join(tasksRoot, name);
      const mjs = join(taskDir, 'task.mjs');
      if (!existsSync(mjs)) continue;
      let decl;
      try {
        // Canonical field names from here on (legacy code-work names accepted at
        // the door, never re-checked downstream).
        decl = normalizeTaskDeclaration((await import(pathToFileURL(mjs).href)).default);
      } catch (e) {
        errors.push({ pack: pack.id, task: name, what: `${relative(root, mjs)} failed to import: ${e.message}`, fix: 'fix or remove the task' });
        continue;
      }
      const problems = validateTaskDeclaration(decl);
      if (problems.length) {
        errors.push({ pack: pack.id, task: name, what: `${relative(root, mjs)} is not a valid task declaration: ${problems.map((p) => p.what).join('; ')}`, fix: problems[0].fix });
        continue;
      }
      // A local pack's dir-name is its id (enforced by the registry); the task's
      // directory name should likewise match its declared id — a mismatch would
      // make the dispatch path and the declaration disagree.
      if (decl.id !== name) {
        errors.push({ pack: pack.id, task: name, what: `task in ${relative(root, taskDir)} declares id "${decl.id}" but its directory is "${name}"`, fix: 'rename the directory to the task id, or set the id to the directory name' });
        continue;
      }
      tasks.push({
        pack: pack.id,
        id: decl.id,
        taskDir,
        taskPath: `${relative(root, taskDir).split('\\').join('/')}/task.md`,
        decl,
      });
    }
  }
  return { tasks, errors };
}
// Executor-side deterministic validation of a dispatch issue, BEFORE any model
// judgment (per-project-scheduling DESIGN §5.2). Given the issue body, it asserts
// in code that the first line is a legal task path, the task file exists at HEAD,
// its pack is declared, and its `task.mjs` sibling parses to a well-formed
// declaration — then resolves the model and outcome ceiling the executor will
// enforce. An invalid dispatch is rejected (the executor de-labels it and
// converges it to needs-human), so a forged or mangled issue never runs.
//
// Pure over injected capabilities so it unit-tests without a repo or GitHub. It
// is NOT a CLI — the executor shell beside it, `resolve-dispatch.mjs`, is what
// drives it in production: that shell takes the issue body out of the label
// event's payload on disk and wires `exists`/`isPackDeclared`/`loadTask` to the
// checkout, so validating a dispatch costs no GitHub call at all.

import { normalizeTaskDeclaration, validateTaskDeclaration } from './task-contract.mjs';
import { resolveModel } from './model-map.mjs';

// The only shape a dispatch first line may take (DESIGN §5.2). Anchored end to
// end — no query strings, no trailing junk, exactly one pack and one task
// segment under a packs/ root. The `.claudinite/(shared|local)/` prefix is
// OPTIONAL: a consumer's task path carries it (its canon is mounted at
// `.claudinite/shared/packs/`, its own packs at `.claudinite/local/packs/`),
// while the CANON repo runs its own tree and dispatches root-relative paths
// (`packs/<pack>/…` for its canon packs, `.claudinite/local/packs/<pack>/…` for
// its local packs). All three forms are legal; nothing else is.
export const DISPATCH_PATH_RE = /^(?:\.claudinite\/(?:shared|local)\/)?packs\/([^/]+)\/tasks\/([^/]+)\/task\.md$/;

// The task path a dispatch body points at — its first line, trimmed.
export const dispatchFirstLine = (body) => String(body ?? '').split('\n')[0].trim();

const reject = (reason, extra = {}) => ({ ok: false, reason, ...extra });

// Validate a dispatch body. Capabilities (all injected for testability):
//   exists(path)        -> boolean   — does this repo-relative path exist at HEAD
//   isPackDeclared(id)  -> boolean   — is this pack active in .claudinite-checks.json
//   loadTask(mjsPath)   -> decl      — load the task.mjs default export (throws on parse error)
// Returns { ok:true, pack, task, taskPath, model, resolvedModel, outcome },
// { ok:false, gone:true, pack, task, reason } — a well-formed dispatch whose task
// the repo NO LONGER CARRIES (file gone, sibling gone, pack undeclared): the
// executor CLOSES the issue as obsolete (owner, 2026-08-06) rather than parking
// it on needs-human, because a task that was removed or deactivated is not an
// anomaly a human needs to triage — or { ok:false, reason } for a genuinely
// malformed dispatch (bad path shape, unparseable declaration), which stays a
// needs-human convergence since it may be forgery or a broken task.
export function validateDispatchBody(body, { exists, isPackDeclared, loadTask }) {
  const firstLine = dispatchFirstLine(body);
  const m = DISPATCH_PATH_RE.exec(firstLine);
  if (!m) return reject(`first line "${firstLine}" is not a valid task path (${DISPATCH_PATH_RE})`);

  const [, pack, task] = m;
  const taskPath = firstLine;
  const mjsPath = taskPath.replace(/task\.md$/, 'task.mjs');

  const gone = (reason) => reject(reason, { gone: true, pack, task });
  if (!exists(taskPath)) return gone(`task file ${taskPath} does not exist at HEAD — the repo no longer carries this task`);
  if (!exists(mjsPath)) return gone(`the task.mjs sibling ${mjsPath} is missing — the repo no longer carries this task`);
  if (!isPackDeclared(pack)) return gone(`pack "${pack}" is not declared in .claudinite-checks.json — this task is not active here`);

  let decl;
  try {
    decl = normalizeTaskDeclaration(loadTask(mjsPath));
  } catch (e) {
    return reject(`${mjsPath} did not parse: ${e.message}`, { pack, task });
  }
  const problems = validateTaskDeclaration(decl);
  if (problems.length) return reject(`${mjsPath} is not a valid task declaration: ${problems.map((p) => p.what).join('; ')}`, { pack, task });

  return {
    ok: true,
    pack,
    task,
    taskPath,
    model: decl.agent_model,
    resolvedModel: resolveModel(decl.agent_model),
    outcome: decl.expected_outcome,
    // The best-effort run bound (task-code-work DESIGN §6): the executor
    // surfaces it into the subagent's brief as "fail after N minutes". Always set
    // for an agentic task (the contract requires it); null for an agentless one.
    executionTimeout: decl.agent_execution_timeout ?? null,
  };
}

