// The scheduler's GitHub WRITES — the small set of issue mutations both dispatch
// mechanisms make, over the injected `gh` reader from signals/gh.mjs. Reads live
// with their callers; these are here so the slot machinery and the work-item queue
// share one implementation of each, rather than two that drift.
//
// LABEL WRITES ARE GRANULAR, ALWAYS (tasks-dispatch DESIGN §4, RESEARCH §2): add
// and remove NAMED labels (POST/DELETE), never write the label SET (PUT). A
// set-write replaces from a stale snapshot and clobbers concurrent transitions —
// a bug class GitHub's own CLI shipped (cli/cli#4861) — and with a tick and
// several executors all moving labels at once, that is a correctness rule rather
// than a style preference.

// Ensure every label exists before any is applied. Load-bearing, not cosmetic:
// GitHub does not create a label when you apply one (the issues API 422s on an
// unknown label), so the thing that assigns a label must guarantee it first.
// Idempotent (201 created / 422 already exists are both success) and self-healing
// — a deleted label reappears on the next run.
export async function ensureLabels(gh, repo, labels) {
  for (const { name, color, description } of labels) {
    const res = await gh(`/repos/${repo}/labels`, { method: 'POST', body: { name, color, description } });
    if (res.status === 201) continue;                       // created to spec — nothing further
    if (res.status === 422) {
      // The NAME is taken; that says nothing about the colour or description. A
      // label GitHub auto-created (applying an unknown name to an issue mints it
      // grey `ededed`, no description) would keep those defaults for good, because
      // POST 422s forever. So reconcile the shape, not just the existence — that
      // is what makes the self-healing claim above true for drift and not only for
      // deletion. PATCH is idempotent: an already-correct label is a no-op write.
      const fix = await gh(`/repos/${repo}/labels/${encodeURIComponent(name)}`, {
        method: 'PATCH', body: { color, description },
      });
      if (fix.status !== 200) console.log(`! could not reconcile label "${name}": ${fix.status}`);
      continue;
    }
    console.log(`! could not ensure label "${name}": ${res.status}`);
  }
}

export const addLabel = (gh, repo, number, name) =>
  gh(`/repos/${repo}/issues/${number}/labels`, { method: 'POST', body: { labels: [name] } });

// A label that is already absent 404s; that is the desired end state, so it is
// success. Nothing here reads the response beyond reporting it.
export const removeLabel = (gh, repo, number, name) =>
  gh(`/repos/${repo}/issues/${number}/labels/${encodeURIComponent(name)}`, { method: 'DELETE' });

// The swap every state transition makes. Remove-then-add, and NOT atomic —
// GitHub has no atomic label swap. That is safe because labels are visibility and
// the pick filter, never the arbiter (the claim comments are); what a torn swap
// CAN leave is an open item wearing no state label at all, which the janitor
// repairs (tasks-dispatch DESIGN §6.2, §11).
export async function swapLabel(gh, repo, number, from, to) {
  await removeLabel(gh, repo, number, from);
  return addLabel(gh, repo, number, to);
}

export const comment = (gh, repo, number, body) =>
  gh(`/repos/${repo}/issues/${number}/comments`, { method: 'POST', body: { body } });

// The ONE sanctioned edit to a comment, and the reason the arbitration record is
// no longer strictly append-only: an executor striking its OWN claim on the way
// out (tasks-dispatch DESIGN §6.2). Only a claim's author ever edits it, so a
// claim can be withdrawn but never forged earlier, and comment ids still give the
// total order arbitration reads.
export const editComment = (gh, repo, commentId, body) =>
  gh(`/repos/${repo}/issues/comments/${commentId}`, { method: 'PATCH', body: { body } });

export const listComments = async (gh, repo, number) => {
  const out = [];
  for (let page = 1; ; page += 1) {
    const { status, json } = await gh(`/repos/${repo}/issues/${number}/comments?per_page=100&page=${page}`);
    if (status !== 200 || !Array.isArray(json) || json.length === 0) break;
    out.push(...json);
    if (json.length < 100) break;
  }
  return out;
};

export const closeIssue = (gh, repo, number, stateReason = 'completed') =>
  gh(`/repos/${repo}/issues/${number}`, { method: 'PATCH', body: { state: 'closed', state_reason: stateReason } });

export async function createIssue(gh, repo, { title, body, labels = [] }) {
  const { status, json } = await gh(`/repos/${repo}/issues`, { method: 'POST', body: { title, body, labels } });
  // The STATUS is read, not just the body (#the-fleet-froze-on-this): a 403 from a
  // repo whose Actions cannot create issues puts an error object where the issue
  // should be, and a body-only destructure turns that refusal into a plausible
  // object whose `.number` is simply undefined.
  return { status, number: status >= 200 && status < 300 ? json?.number ?? null : null, json };
}

export const readIssue = async (gh, repo, number) => {
  const { status, json } = await gh(`/repos/${repo}/issues/${number}`);
  return status === 200 ? json : null;
};
===
// Reading the queue. One rule, and it is load-bearing: the work-item list comes
// from the ISSUES list API, never the search index. Search is eventually
// consistent (S6/F11), and a family list that misses a just-created item is
// exactly how a second standing item — a double execution — gets minted.

import { WORK_PREFIX, labelNames } from './work-item.mjs';

const project = (i) => ({
  number: i.number,
  title: i.title,
  body: i.body ?? '',
  state: i.state,
  labels: labelNames(i),
  created_at: i.created_at,
  closed_at: i.closed_at ?? null,
  updated_at: i.updated_at,
});

// Every OPEN work item, oldest first. The whole queue is a page or two: a repo's
// standing items are one per scheduled task, plus whatever ad-hoc work exists.
export async function listOpenWorkItems(gh, repo) {
  const out = [];
  for (let page = 1; ; page += 1) {
    const { status, json } = await gh(`/repos/${repo}/issues?state=open&sort=created&direction=asc&per_page=100&page=${page}`);
    if (status !== 200 || !Array.isArray(json) || json.length === 0) break;
    for (const i of json) {
      if (i.pull_request) continue;
      if (!(i.title ?? '').startsWith(WORK_PREFIX)) continue;
      out.push(project(i));
    }
    if (json.length < 100) break;
  }
  return out;
}
===
// The one vendored place that maps a task's declared model FAMILY to the model
// the executor dispatches its subagent at (per-project-scheduling DESIGN §1, §3).
// A model-generation bump is a single edit HERE — task files and the executor
// only ever speak in families, never concrete ids.
//
// The resolved value is what the executor passes as the subagent's model. Short
// family names are themselves valid model selectors, so they are the safe
// default; to pin a task tier to a concrete dated snapshot, change only that
// family's value in MODEL_MAP below (nothing else needs to move).

export const MODEL_FAMILIES = ['opus', 'sonnet', 'haiku', 'none'];

// family → the model the executor dispatches at. `none` is agentless (the worker
// is code the scheduler runs inline — no subagent, no model), so it maps to null.
export const MODEL_MAP = {
  opus: 'opus',
  sonnet: 'sonnet',
  haiku: 'haiku',
  none: null,
};

// `none` means "pure code, no agent" (DESIGN §1) — the scheduler runs the
// worker .mjs as code-work rather than handing off to an agent session.
export const isAgentless = (family) => family === 'none';

// Resolve a family to its concrete model, or throw on an unknown family (the
// task-declaration-shape check is the author-time guard; this is the runtime
// backstop for the executor/validator).
export function resolveModel(family) {
  if (!Object.prototype.hasOwnProperty.call(MODEL_MAP, family)) {
    throw new Error(`unknown model family "${family}" — valid families: ${MODEL_FAMILIES.join(', ')}`);
  }
  return MODEL_MAP[family];
}
===
// The janitor's queue rules (tasks-dispatch DESIGN §11) — the recovery that needs
// judgment or a longer horizon than the tick's hourly label mechanics. Four rules,
// pure, each returning the items it claims plus the comment it would post; the
// janitor task's worker is the only I/O shell over them.
//
// What is NOT here: the executing-leash reclaim, which rides the tick (a
// deterministic label rule, serialized and hourly, recovering a dead executor's
// item in ~2h instead of ~25h). That amends the single-recovery-site split in
// siting, not in principle — recovery still happens once, in one place per rule,
// in code, and never as a sweep inside a session that is executing something.

import { periodMs } from './anchors.mjs';
import {
  READY, AGENT, BLOCKED, NEEDS_HUMAN, STATE_LABELS,
  parseWorkItemTitle, parseWorkItemBody, hasLabel, labelNames,
} from './work-item.mjs';

export const AGENT_LEASH_MS = 3 * 3600e3;
export const STALE_READY_PERIODS = 2;
export const STUCK_BLOCKED_MS = 2 * 86400e3;

const ms = (t) => (t == null ? null : new Date(t).getTime());
const idle = (item, now) => ms(now) - (ms(item.updated_at) ?? ms(item.created_at) ?? ms(now));

// Rule A — STALE READY. An item no executor picked for ~2 of its own periods comes
// out of the queue as a human's problem. The period is read from the task's
// declared `frequency` at HEAD (no title parsing — that was the slot grammar); an
// item whose task is unknown falls back to a day.
export function staleReadyItems(open = [], now, { periodFor = () => null, factor = STALE_READY_PERIODS } = {}) {
  return open.filter((i) => {
    if (!hasLabel(i, READY) || hasLabel(i, NEEDS_HUMAN)) return false;
    const parsed = parseWorkItemTitle(i.title);
    if (!parsed) return false;
    const per = periodFor(`${parsed.pack}/${parsed.task}`) ?? 86400e3;
    // `readySince` is the item's last touch: every transition into ready is a
    // label write, so an item that has sat unread since then has not been touched.
    return idle(i, now) >= factor * per;
  });
}

export const staleReadyComment = (item) => {
  const p = parseWorkItemTitle(item.title);
  return `This work item for ${p ? `${p.pack}/${p.task}` : 'this task'} has sat \`${READY}\` for over ~${STALE_READY_PERIODS} of its scheduling periods `
    + `without an executor picking it up. Labeling \`${NEEDS_HUMAN}\` and taking it out of the queue for triage.`;
};

// Rule B — THE AGENT LEASH. `task:agent` silent past ~3h means the session died.
// The hand-off comment names which session, so the escalation can say so. The
// assumption is stated rather than discovered: a legitimately longer-running agent
// must comment on its item to reset the activity clock, or it is declared dead.
export function deadAgentItems(open = [], now, { leashMs = AGENT_LEASH_MS } = {}) {
  return open.filter((i) => hasLabel(i, AGENT) && !hasLabel(i, NEEDS_HUMAN) && idle(i, now) >= leashMs);
}

export const deadAgentComment = (item, sessionNote = null) =>
  `This work item has carried \`${AGENT}\` for over ${Math.round(AGENT_LEASH_MS / 3600e3)}h with no activity — `
  + `the agent session that claimed it${sessionNote ? ` (${sessionNote})` : ''} never converged it. Labeling \`${NEEDS_HUMAN}\` for triage.`;

// Rule C — THE STUCK-DEPENDENCY SWEEP (F14). The stale-ready rule cannot see this
// at all: a blocked item is never ready. So a blocked item whose blockers have not
// resolved past the bound gets an escalation COMMENT and nothing else — labels
// untouched, so the item still proceeds by itself the moment its blockers resolve,
// and a human who decides it is dead closes it by hand.
//
// Sleeping items (a future `Not-before`, blockers closed) never match: waiting for
// a time is the mechanism working.
export function stuckBlockedItems(open = [], now, { stateOf = () => null, boundMs = STUCK_BLOCKED_MS } = {}) {
  return open.filter((i) => {
    if (!hasLabel(i, BLOCKED) || hasLabel(i, NEEDS_HUMAN)) return false;
    const { blockedBy } = parseWorkItemBody(i.body);
    if (!blockedBy.length) return false;
    if (blockedBy.every((n) => stateOf(n) === 'closed')) return false;
    return ms(now) - ms(i.created_at) >= boundMs;
  });
}

export const stuckBlockedComment = (item, unresolved) =>
  `This work item has been blocked on ${unresolved.map((n) => `#${n}`).join(', ')} for over `
  + `${Math.round(STUCK_BLOCKED_MS / 86400e3)} days. Nothing here is stuck mechanically — it will proceed by itself the moment those close — `
  + 'but if they are never going to, close this item by hand.';

// Rule D — THE STATELESS-ITEM REPAIR. An open work item wearing neither a `task:*`
// state nor `needs-human` is off the state machine entirely: a torn label swap's
// leavings (an executor that died between the remove and the add), invisible to
// every rule that filters by state. It converges to triage — the same posture a
// malformed item gets.
export function statelessItems(open = []) {
  return open.filter((i) => {
    const names = labelNames(i);
    return !names.includes(NEEDS_HUMAN) && !STATE_LABELS.some((l) => names.includes(l));
  });
}

export const statelessComment = () =>
  'This work item carries no state label at all — the leavings of a label swap that tore mid-flight, which puts it outside the state machine. '
  + `Labeling \`${NEEDS_HUMAN}\`: re-queue it by hand (remove \`${NEEDS_HUMAN}\`, add \`${READY}\`) once you have looked at it.`;

// The period of a task, for rule A — read from the declaration at HEAD.
export const periodForTasks = (tasks = []) => {
  const byId = new Map(tasks.map((t) => [`${t.pack}/${t.id}`, t]));
  return (id) => periodMs(byId.get(id)?.decl?.frequency);
};

