// @deprecated Nothing writes this since the approval park: a run that left an
// unmerged PR no longer CLOSES as delivered, it parks at
// `task:needs-human-approval` and waits to be merged. Kept exported, kept in
// `QUEUE_LABELS`, and still read everywhere it was read — closed issues carrying
// it are stored data, and a decoder that stopped recognising it would turn every
// historical delivered run into an un-outcomed one.
export const OUTCOME_DELIVERED = 'outcome:delivered';

// @deprecated The pre-2026-08-19 spellings of the two terminals above. Kept
// exported so a fielded pack that imports them still loads, and READ everywhere
// the terminals are read: labels are stored data on closed issues fleet-wide, so
// a decoder that stopped recognising these would turn every historical run into
// an un-outcomed one. Write `TASK_DONE` / `TASK_OBSOLETE`.
export const OUTCOME_DONE = 'outcome:done';
export const OUTCOME_OBSOLETE = 'outcome:obsolete';

// Every legacy terminal spelling, mapped STRAIGHT to today's — never chained one
// normalization onto the last, so a label written for the oldest vocabulary
// resolves in a single pass however many renames it has outlived.
const LEGACY_TERMINALS = Object.freeze({
  [OUTCOME_DONE]: TASK_DONE,
  [OUTCOME_OBSOLETE]: TASK_OBSOLETE,
});

// The terminals in the order a reader should prefer them, canonical spellings only.
export const TERMINAL_LABELS = Object.freeze([TASK_DONE, OUTCOME_DELIVERED, TASK_OBSOLETE]);

// The one decoder for "how did this item end", in today's vocabulary whatever
// spelling the issue actually carries. Null means the item wears no terminal at
// all — an item still open, or one closed by hand.
export function terminalOfLabels(labels = []) {
  for (const l of labels) {
    if (TERMINAL_LABELS.includes(l)) return l;
    if (LEGACY_TERMINALS[l]) return LEGACY_TERMINALS[l];
  }
  return null;
}

export const terminalOf = (item) => terminalOfLabels(labelNames(item));

