60	  return open
61	    .filter((i) => hasLabel(i, READY) && !hasLabel(i, NEEDS_HUMAN))
62	    .filter((i) => !open.some((o) => o.number !== i.number && titleOf(o) === titleOf(i)
63	      && (hasLabel(o, EXECUTING) || hasLabel(o, AGENT))))
64	    .filter((i) => {
65	      if (!standing(i)) return true;
66	      return !taskAfter(taskIdOf(i)).some(liveUpstream);
67	    })
68	    .sort((a, b) =>
69	      (hasLabel(b, URGENT) ? 1 : 0) - (hasLabel(a, URGENT) ? 1 : 0)
70	      || new Date(a.created_at) - new Date(b.created_at)
71	      || a.number - b.number);
72	}
73	
74	// The claim comment carries WHO and WHEN — the executor id and its run URL —
75	// because executor identity is an unbounded set and must never become a label
76	// (DESIGN §4).
77	export const claimComment = ({ executor, runUrl, at }) =>
78	  `${CLAIM_MARKER}\nClaimed by executor \`${executor}\` at ${at}.${runUrl ? `\n\nRun: ${runUrl}` : ''}`;
79	
