81	// each an implicit assumption made explicit:
82	//
83	//  - "EARLIEST" MEANS LOWEST COMMENT ID, never timestamp. GitHub comment
84	//    `created_at` has one-second granularity, so simultaneous claims tie on time;
85	//    comment ids are server-assigned and strictly increasing — a total order the
86	//    protocol gets for free. Nothing here compares runner clocks.
87	//  - THE ARBITER IS EPISODE-SCOPED (F18): the earliest claim SINCE the item last
88	//    became ready. Over an item's lifetime dead claims accumulate (every reclaim
89	//    and revert leaves one), and arbitrating over all of them makes a dead claim
90	//    outrank every future live claimant — the item then livelocks through reclaim
91	//    cycles forever. The reclaim / revert / re-queue comment is the boundary.
92	//  - THE LABEL SWAP IS NOT THE ARBITER, so a torn swap can never mint a second
93	//    owner; it can only leave an item with no state label, which the janitor
94	//    repairs.
95	export function claimWinner(comments = []) {
96	  const sorted = [...comments].sort((a, b) => a.id - b.id);
97	  const boundary = sorted.filter((c) => (c.body ?? '').includes(EPISODE_MARKER)).at(-1);
98	  const claims = sorted
99	    .filter((c) => (c.body ?? '').includes(CLAIM_MARKER))
100	    .filter((c) => !boundary || c.id > boundary.id);
101	  return claims[0] ?? null;
102	}
