105	// filters read possibly-stale state, so two executors can pass them simultaneously
106	// and claim DIFFERENT items the filters should have serialized — a twin pair, or
107	// an upstream and its dependent. The per-item lease cannot see that: it protects
108	// one item, not one title. If a conflicting item now holds an EARLIER claim
109	// (comment id — the same arbiter the lease trusts), this executor reverts its own
110	// claim and moves on. Bounded, deterministic, and the earlier claim never notices.
111	export function conflictsWithEarlierClaim(item, myClaimId, others, { taskAfter = () => [], frequencyOf = () => null } = {}) {
112	  const standing = (i) => isStandingItem(i, frequencyOf(taskIdOf(i)));
113	  const upstreams = standing(item) ? taskAfter(taskIdOf(item)) : [];
114	  return others.some((o) => {
115	    if (o.number === item.number) return false;
116	    if (!(hasLabel(o, EXECUTING) || hasLabel(o, AGENT))) return false;
117	    const conflicting = titleOf(o) === titleOf(item)
118	      || (upstreams.includes(taskIdOf(o)) && standing(o));
119	    return conflicting && o.claimId != null && o.claimId < myClaimId;
120	  });
121	}
