124	// with the task's next anchor, ready → blocked, the reason recorded — so the item
125	// itself carries "asked, declined, wakes at T" and the tick is a pure function of
126	// the clock and the issue list. An AD-HOC item has no next anchor to roll to, so
127	// it closes obsolete with the reason commented (a follow-up whose world settled on
128	// its own, S17).
129	export function noGoPlan(item, task, schedule, now, reason) {
130	  if (!isStandingItem(item, task?.decl?.frequency)) {
131	    return { kind: 'close', outcome: TASK_OBSOLETE, stateReason: 'not_planned', reason };
132	  }
133	  const until = nextAnchor(task.decl.frequency, schedule, now);
134	  return { kind: 'roll', until: until ? until.toISOString() : null, reason };
135	}
