1	// The two operator levers (tasks-dispatch DESIGN §8), which are the whole of
2	// urgency, forcing, fan-out and retry:
3	//
4	//   create-work-item <pack>/<task> [--urgent] [--context …] [--not-before ISO]
5	//                                  [--blocked-by #N,#M] [--qualifier text]
6	//                                  [--supersedes #N]
7	//   create-work-item --wake <#N> [--urgent]
8	//
9	// FORCING A SCHEDULED TASK IS WAKING ITS STANDING ITEM — strip `task:blocked`,
10	// clear `Not-before`, optionally add `task:urgent`. The same lever as the human
11	// re-queue out of `needs-human`, which is no accident: "run this now" and "retry
12	// this now" are the same operation on the same object. The executor still
13	// evaluates the precondition at pick, so a force that finds no work SAYS so where
14	// the operator reads it. The slot scheduler's whole forcing apparatus — its override
15	// bag, the forced-verdict path, the `~f` slot marker and the watermark exclusion —
16	// reduced to these two levers and was deleted (#974).
17	//
18	// FORCING AD-HOC WORK IS CREATING AN ITEM — a parameterized run, a `manual` task,
19	// a fan-out target. Ad-hoc is STRUCTURAL (DESIGN §15.26): a `manual` task has no
20	// anchor to stand for, and a qualified title is a different title from the standing
21	// one — so such an item is invisible to the tick's guards in both directions,
22	// neither suppressing tomorrow's occurrence nor consuming it. Which is why an
23	// UNQUALIFIED item for a scheduled task is refused below: it would BE that task's
24	// standing item, and the tick's dedupe would close one of the two.
25	
26	import { pathToFileURL } from 'node:url';
27	import {
28	  READY, BLOCKED, URGENT, NEEDS_HUMAN, TASK_OBSOLETE, QUEUE_LABELS,
29	  EPISODE_MARKER, workItemTitle, workItemBody, withNotBefore, hasLabel,
30	} from './work-item.mjs';
31	
32	// The Context a hand-created item carries when the operator names none. Generic
33	// on purpose — it names the mechanism, not the task — because an item's Context is
34	// the agent's binding scope, and a forced item that carried none would read as a
35	// scope of nothing.
36	export const FORCED_CONTEXT =
37	  'Created by hand — no precondition asserts there is work to do. Do only what the task file specifies, and converge to a no-op if there is nothing.';
38	
39	export function parseArgs(argv) {
40	  const out = { urgent: false, context: [], blockedBy: [], notBefore: null, qualifier: null, supersedes: null, wake: null, target: null };
41	  for (let i = 0; i < argv.length; i += 1) {
42	    const a = argv[i];
43	    const next = () => argv[++i];
44	    if (a === '--urgent') out.urgent = true;
45	    else if (a === '--wake') out.wake = Number(String(next()).replace('#', ''));
46	    else if (a === '--context') out.context.push(next());
47	    else if (a === '--not-before') out.notBefore = next();
48	    else if (a === '--qualifier') out.qualifier = next();
49	    else if (a === '--supersedes') out.supersedes = Number(String(next()).replace('#', ''));
50	    else if (a === '--blocked-by') out.blockedBy.push(...String(next()).split(',').map((s) => Number(s.trim().replace('#', ''))).filter(Boolean));
51	    else if (!a.startsWith('--')) out.target = a;
52	  }
53	  return out;
54	}
55	
56	// Wake an item: clear its wait and put it back in the queue. Also the sanctioned
57	// road back from `needs-human` — nothing MECHANICAL ever re-queues a triage item,
58	// and the next pickup re-runs the precondition, which is what makes the retry safe
59	// even when the failed run half-did its work.
60	export async function wakeItem(gh, repo, number, { urgent = false } = {}) {
61	  const api = await import('../github.mjs');
62	  const issue = await api.readIssue(gh, repo, number);
63	  if (!issue) return { ok: false, error: `#${number} could not be read` };
64	  const body = withNotBefore(issue.body ?? '', null);
65	  if (body !== issue.body) await gh(`/repos/${repo}/issues/${number}`, { method: 'PATCH', body: { body } });
66	  // The episode boundary: every claim before this moment is dead, and arbitrating
67	  // over dead claims is what livelocks an item through reclaim cycles forever.
68	  await api.comment(gh, repo, number, `${EPISODE_MARKER}\nWoken by hand — cleared \`Not-before\` and returned this item to the queue.`);
69	  for (const l of [BLOCKED, NEEDS_HUMAN]) if (hasLabel(issue, l)) await api.removeLabel(gh, repo, number, l);
70	  await api.addLabel(gh, repo, number, READY);
71	  if (urgent) await api.addLabel(gh, repo, number, URGENT);
72	  return { ok: true, number };
73	}
74	
75	export async function createWorkItem(gh, repo, { pack, task, taskPath, frequency = null, opts, log = console.log }) {
76	  const api = await import('../github.mjs');
77	  const { listOpenWorkItems } = await import('./read.mjs');
78	  const title = workItemTitle({ pack, task, qualifier: opts.qualifier });
79	
80	  // An unqualified item for a SCHEDULED task is that task's standing item by
81	  // construction, not a run beside it — the tick would treat the pair as duplicate
82	  // standing items and close the younger. The two levers that do what the operator
83	  // meant are named rather than guessed at.
84	  if (frequency !== null && frequency !== 'manual' && !opts.qualifier) {
85	    return { ok: false, error: `${pack}/${task} runs on a \`${frequency}\` schedule, so an unqualified item for it IS its standing item — the tick would close one of the two as a duplicate. To run it now, wake its standing item (\`--wake #N\`, or the scheduler workflow's \`wake\` input); to run it beside the schedule, give this item a \`--qualifier\` naming what makes it a different run.` };
86	  }
87	
88	  // The pick-time mutex means a new item QUEUES behind an open twin rather than
89	  // running beside it, and the operator should know they are queueing, not jumping.
90	  const twin = (await listOpenWorkItems(gh, repo)).find((i) => (i.title ?? '').trim() === title);
91	  if (twin) log(`! #${twin.number} is an open item with this exact title — the new item will queue behind it, not run beside it`);
92	
93	  await api.ensureLabels(gh, repo, QUEUE_LABELS);
94	  const blocked = opts.notBefore !== null || opts.blockedBy.length > 0;
95	  const res = await api.createIssue(gh, repo, {
96	    title,
97	    body: workItemBody({
98	      taskPath,
99	      notBefore: opts.notBefore,
100	      blockedBy: opts.blockedBy,
101	      context: opts.context.length ? opts.context : [FORCED_CONTEXT],
102	    }),
103	    labels: [blocked ? BLOCKED : READY, ...(opts.urgent ? [URGENT] : [])],
104	  });
105	  if (!res.number) return { ok: false, error: `could not create the item: ${res.status}` };
106	
107	  if (opts.supersedes) {
108	    await api.comment(gh, repo, opts.supersedes, `Superseded by #${res.number}, a retry of this work created by hand.`);
109	    await api.addLabel(gh, repo, opts.supersedes, TASK_OBSOLETE);
110	    await api.closeIssue(gh, repo, opts.supersedes, 'not_planned');
111	  }
112	  return { ok: true, number: res.number };
113	}
