import {
  NEEDS_HUMAN, OUTCOME_DONE, OUTCOME_DELIVERED, OUTCOME_OBSOLETE,
} from '../../engine/scheduler/queue/work-item.mjs';
import { isWorkItem } from './model.mjs';

export const DAY_MS = 86400e3;

const ms = (t) => (t == null ? null : new Date(t).getTime());

// A UTC day. The queue's anchors, the digests' file names and GitHub's timestamps are
// all UTC, so a local-time bucketing would put a member's midnight run on the wrong
// day depending on who is looking.
export const dayKey = (t) => new Date(t).toISOString().slice(0, 10);

// The window's days, oldest first, including today. Built from keys rather than from
// arithmetic on a rendered date so a DST-free UTC ladder is the only thing anyone has
// to trust.
export function dayLadder(now, days) {
  const start = Math.floor(now / DAY_MS) * DAY_MS - (days - 1) * DAY_MS;
  return Array.from({ length: days }, (_, i) => dayKey(start + i * DAY_MS));
---
//   repo or a rate-limit stumble cannot blank the page.

import { periodMs } from '../../engine/scheduler/queue/anchors.mjs';
import {
  BLOCKED, READY, EXECUTING, AGENT, NEEDS_HUMAN, URGENT,
  OUTCOME_DONE, OUTCOME_DELIVERED, OUTCOME_OBSOLETE,
} from '../../engine/scheduler/queue/work-item.mjs';
import { describeItem, isWorkItem, parseWorkItemTitle, taskDeclarationPaths } from './model.mjs';

// Severity ladder, worst first. The order IS the sort, so it is stated once here
// rather than implied by comparisons scattered through the render.
export const LEVELS = ['critical', 'serious', 'warning', 'info', 'ok'];
const levelRank = (l) => {
  const i = LEVELS.indexOf(l);
  return i === -1 ? LEVELS.length : i;
};
---
import {
  EXECUTING_LEASH_MS, AGENT_LEASH_MS, STALE_READY_PERIODS, STUCK_BLOCKED_MS,
} from '../../engine/scheduler/queue/leases.mjs';
import {
  WORK_PREFIX, BLOCKED, READY, URGENT, EXECUTING, AGENT, NEEDS_HUMAN,
  OUTCOME_DONE, OUTCOME_DELIVERED, OUTCOME_OBSOLETE, STATE_LABELS,
  TRIAGE_LABELS, NEEDS_HUMAN_ACTION, NEEDS_HUMAN_DECISION, NEEDS_HUMAN_APPROVAL,
  NEEDS_HUMAN_FAILURE, isBlockingPark,
  CLAIM_MARKER, HANDOFF_MARKER, EPISODE_MARKER,
  parseWorkItemTitle, parseWorkItemBody, hasLabel, labelNames,
} from '../../engine/scheduler/queue/work-item.mjs';

export {
  WORK_PREFIX, BLOCKED, READY, URGENT, EXECUTING, AGENT, NEEDS_HUMAN,
  OUTCOME_DONE, OUTCOME_DELIVERED, OUTCOME_OBSOLETE,
  EXECUTING_LEASH_MS, AGENT_LEASH_MS, STUCK_BLOCKED_MS, STALE_READY_PERIODS,
  parseWorkItemTitle, nextAnchor, mostRecentAnchor, periodMs,
};

---
// Shared rendering vocabulary. Both views draw from this so a state, a duration or a
// severity looks and reads the same whether you are looking at one repo or twelve —
// a fleet page whose "blocked" chip differs from the repo page's is a page you have
// to learn twice.

import {
  BLOCKED, READY, EXECUTING, AGENT, NEEDS_HUMAN,
  OUTCOME_DONE, OUTCOME_DELIVERED, OUTCOME_OBSOLETE,
} from '../../engine/scheduler/queue/work-item.mjs';

export const $ = (id) => document.getElementById(id);

export const el = (tag, props = {}, kids = []) => {
